BEGIN
    -- 1. Subject Insertion / Resolution
    SELECT id INTO v_subject_id FROM subjects WHERE name_bn = 'ফিন্যান্স ও ব্যাংকিং' LIMIT 1;
    IF v_subject_id IS NULL THEN
        INSERT INTO subjects (name_bn, name_en, icon_url)
