        RETURNING id INTO v_subject_id;
        RAISE NOTICE 'Created subject: %', v_subject_id;
    ELSE
        UPDATE subjects SET icon_url = 'https://img.icons8.com/color/96/bank-building.png', name_en = 'Finance and Banking' WHERE id = v_subject_id;
        RAISE NOTICE 'Found existing subject: %', v_subject_id;
    END IF;

    -- Chapter 1: অর্থায়ন ও ব্যবসায় অর্থায়ন
    SELECT id INTO v_chapter_id FROM chapters WHERE subject_id = v_subject_id AND order_index = 1 LIMIT 1;
    IF v_chapter_id IS NULL THEN
        INSERT INTO chapters (subject_id, title_bn, title_en, order_index)
        VALUES (v_subject_id, 'অর্থায়ন ও ব্যবসায় অর্থায়ন', 'Finance and Business Finance', 1)
        RETURNING id INTO v_chapter_id;
    ELSE
        UPDATE chapters SET title_bn = 'অর্থায়ন ও ব্যবসায় অর্থায়ন', title_en = 'Finance and Business Finance', order_index = 1 WHERE id = v_chapter_id;
    END IF;

    DELETE FROM lessons WHERE chapter_id = v_chapter_id;
    DELETE FROM exam_questions WHERE chapter_id = v_chapter_id;

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ১ম অধ্যায়: অর্থায়ন ও ব্যবসায় অর্থায়ন (Finance and Business Finance)

---

### ১.১ অর্থায়নের ধারণা (Concept of Finance)
অর্থায়ন বলতে তহবিল সংগ্রহ, এর সংরক্ষণ, সুষ্ঠু বণ্টন ও লাভজনক খাতে বিনিয়োগ সংক্রান্ত সামগ্রিক পরিকল্পনা ও কার্যক্রমকে বোঝায়। একটি ব্যবসায় প্রতিষ্ঠান কীভাবে তহবিল সংগ্রহ করবে, কোন কোন সম্পদে তা বিনিয়োগ করবে এবং অর্জিত মুনাফা কীভাবে মালিকদের মধ্যে বণ্টন করবে—অর্থায়ন মূলত এই সকল গুরুত্বপূর্ণ সিদ্ধান্ত নিয়ে আলোচনা করে।

> 📌 **সংজ্ঞা:** *"Finance is the art and science of managing money."* — অর্থায়ন হলো অর্থ ও তহবিল ব্যবস্থাপনার একটি সুসংগঠিত বিজ্ঞান ও কলা।

---

### ১.২ অর্থায়নের ক্রমবিকাশের ইতিহাস (Evolution of Finance)
অর্থায়ন আধুনিক যুগে রাতারাতি রূপ লাভ করেনি। বিভিন্ন দশকের অর্থনৈতিক পরিস্থিতি ও সংকটের মধ্য দিয়ে এটি বিবর্তিত হয়েছে:

| সময়কাল | ঐতিহাসিক প্রেক্ষাপট ও অর্থায়নের মূল গতিধারা |
| :--- | :--- |
| **১৯৩০-এর পূর্ববর্তী দশক** | মূলত ব্যবসায়ের একত্রীকরণ (Merger), শেয়ার ইস্যু ও তহবিল সংগ্রহের আনুষ্ঠানিক আইনগত দিকগুলোর ওপর জোর দেওয়া হতো। |
| **১৯৩০-এর দশক (মহামন্দার যুগ)** | বিশ্ব অর্থনৈতিক মহামন্দা (Great Depression)-এর কারণে প্রতিষ্ঠানের দেউলিয়াত্ব রোধ, দায় পরিশোধ ক্ষমতা ও ঋণ কাঠামো নিয়ন্ত্রণের ওপর গুরুত্ব দেওয়া হয়। |
| **১৯৪০-এর দশক** | নগদ প্রবাহ বিশ্লেষণ এবং তারল্য সংরক্ষণের প্রয়োজনীয়তা তীব্রভাবে অনুভূত হয়। |
| **১৯৫০-এর দশক** | আধুনিক অর্থায়নের সূচনা। মূলধন বাজেটিং (Capital Budgeting) পদ্ধতি ও ভবিষ্যৎ বিনিয়োগের আর্থিক মূল্যায়নের সূচনা হয়। |
| **১৯৬০-এর দশক** | আধুনিক পোর্টফোলিও তত্ত্ব, ঝুঁকি ও প্রতিদানের গাণিতিক সম্পর্ক এবং মূলধন কাঠামো তত্ত্বের ব্যাপক প্রসার ঘটে। |
| **১৯৭০-এর দশক** | কম্পিউটার প্রযুক্তির ব্যবহার শুরু হয় এবং আন্তর্জাতিক আর্থিক বাজার ও বিকল্প বিনিয়োগের পথ উন্মোচিত হয়। |
| **১৯৮০-এর দশক** | প্রতিষ্ঠানের অভ্যন্তরীণ মূলধন ব্যয় ও শেয়ারহোল্ডারদের সম্পদ সর্বাধিকরণ অর্থায়নের প্রধান লক্ষ্য হিসেবে প্রতিষ্ঠিত হয়। |
| **১৯৯০-এর দশক থেকে বর্তমান** | বিশ্বায়ন (Globalization), অনলাইন ফিনটেক ও তথ্যপ্রযুক্তির উৎকর্ষতায় আন্তর্জাতিক আর্থিক লেনদেন ও ঝুঁকি ব্যবস্থাপনার যুগ। |

---

### ১.৩ ব্যবসায় অর্থায়নের গুরুত্ব (Importance of Business Finance)
১. **ব্যবসায়িক মূলধন সংকট মোকাবেলা:** স্বল্প মূলধন নিয়ে কীভাবে সর্বোচ্চ উৎপাদনশীল কার্যক্রম পরিচালনা করা যায় তার সঠিক পথনির্দেশনা দেয়।
২. **অনগ্রসর ব্যাংক ব্যবস্থার ক্ষতিপূরণ:** উন্নয়নশীল দেশে প্রাতিষ্ঠানিক ঋণের সীমাবদ্ধতা থাকা সত্ত্বেও বিভিন্ন বিকল্প উৎসের সন্ধান করে।
৩. **উৎপাদনশীল বিনিয়োগ ও মুনাফা নিশ্চিতকরণ:** অপরিকল্পিত বিনিয়োগ পরিহার করে লাভজনক প্রকল্পে মূলধন খাঁটিয়ে প্রতিষ্ঠানের দীর্ঘমেয়াদী অস্তিত্ব টিকিয়ে রাখে।

---

### ১.৪ ব্যবসায় অর্থায়নের নীতিমালা (Principles of Business Finance)
ব্যবসায়ের আর্থিক সাফল্য নির্ভর করে তিনটি মৌলিক নীতির যথাযথ অনুসরণের ওপর:

#### ১. তারল্য বনাম মুনাফা নীতি (Liquidity vs Profitability Principle)
- প্রতিষ্ঠানে সার্বক্ষণিক কাঁচামাল ক্রয়, শ্রমিকের বেতন ও দৈনন্দিন খরচ মেটানোর জন্য নগদ অর্থ প্রয়োজন; একে **তারল্য (Liquidity)** বলে।
- অপরদিকে বেশি মুনাফা পেতে হলে অর্থকে অলস ফেলে না রেখে লাভজনক খাতে বিনিয়োগ করতে হয়।
- অতিরিক্ত নগদ টাকা সংরক্ষণ করলে ব্যবসায় নিরাপদ থাকে কিন্তু সম্ভাব্য মুনাফা থেকে বঞ্চিত হতে হয়; আবার অতিরিক্ত বিনিয়োগ করলে মুনাফা বাড়লেও দৈনন্দিন দেনা পরিশোধে ব্যর্থ হয়ে দেউলিয়া হওয়ার ঝুঁকি বাড়ে।
- আর্থিক ব্যবস্থাপকের কাজ হলো তারল্য ও মুনাফার মধ্যে একটি কাম্য ভারসাম্য (Optimal Trade-off) তৈরি করা।

#### ২. উপযুক্ততার নীতি (Principle of Suitability)
- স্বল্পমেয়াদী প্রয়োজন মেটানোর জন্য স্বল্পমেয়াদী উৎস হতে এবং দীর্ঘমেয়াদী স্থায়ী সম্পদ অর্জনের জন্য দীর্ঘমেয়াদী উৎস হতে অর্থ সংগ্রহ করতে হবে।
- **উদাহরণ:** চলতি খরচ (যেমন: মজুরি, কাঁচামাল) বাণিজ্যিক ব্যাংক ঋণ বা পাওনাদারের কাছ থেকে মেটানো উচিত; অন্যদিকে কারখানা বা জমি ক্রয়ের জন্য শেয়ার বিক্রি বা দীর্ঘমেয়াদী ঋণপত্র ইস্যু করা সমীচীন।

#### ৩. ব্যবসায়ের বৈচিত্র্যায়ন ও ঝুঁকি বণ্টন নীতি (Diversification & Risk Sharing)
- "একঝুড়িতে সব ডিম রেখো না" (Do not put all eggs in one basket) — এই নীতির মূল ভিত্তি।
- কোনো বিনিয়োগকারী বা প্রতিষ্ঠান সব মূলধন একটিমাত্র পণ্যে বা ব্যবসায়ে বিনিয়োগ না করে একাধিক ভিন্নধর্মী পণ্যে বিনিয়োগ করবে।
- এতে একটি পণ্যের বাজার পড়ে গেলেও অন্য পণ্যের বিক্রি ও মুনাফা দিয়ে সামগ্রিক ব্যবসায় টিকে থাকে।
', 1);

