### উদ্দীপক:
> জনাব রফিকুল ইসলাম একটি প্লাস্টিক সামগ্রী প্রস্তুতকারী কারখানার স্বত্বাধিকারী। সাম্প্রতিককালে কাঁচামালের মূল্য বৃদ্ধি পাওয়ায় তিনি ব্যাংকের স্বল্পমেয়াদী চলতি ঋণ থেকে অর্থ নিয়ে নতুন ভারী যন্ত্রপাতি ক্রয় করেন। কিন্তু শ্রমিকদের নিয়মিত মজুরি ও কাঁচামাল ক্রয়ের জন্য প্রয়োজনীয় নগদ অর্থের তীব্র সংকট দেখা দেয়। অন্যদিকে কারখানাটিতে অধিক মুনাফার আশায় তিনি সব অর্থ একটিমাত্র পণ্যের উৎপাদনে বিনিয়োগ করেছিলেন। ফলে বাজারে ওই পণ্যের চাহিদা হ্রাস পাওয়ায় ব্যবসায় ব্যাপক ক্ষতির সম্মুখীন হয়।

---

### প্রশ্নাবলি:
- **(ক)** অর্থায়ন কাকে বলে? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** তারল্য বনাম মুনাফা নীতি বলতে কী বোঝায়? ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** জনাব রফিকুল ইসলাম অর্থায়নের কোন নীতিটি লঙ্ঘন করে নগদ সংকটে পড়েছেন? ছক ও উদ্দীপকের আলোকে ব্যাখ্যা কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** জনাব রফিকুলের ব্যবসায় ক্ষতির সম্মুখীন হওয়ার কারণ অর্থায়নের ''ব্যবসায়ের বৈচিত্র্যায়ন ও ঝুঁকি বণ্টন'' নীতির আলোকে ছকের মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
তহবিল সংগ্রহ, এর সুষ্ঠু ব্যবস্থাপনা ও সঠিক লাভজনক ক্ষেত্রে দক্ষ বিনিয়োগ সংক্রান্ত যাবতীয় কার্যক্রমের সমষ্টিকে অর্থায়ন (Finance) বলে।

#### (খ) অনুধাবনমূলক উত্তর:
নগদ টাকা হাতে রাখা (তারল্য) এবং অধিক মুনাফা অর্জনের জন্য বিনিয়োগ করার মধ্যকার ভারসাম্য রক্ষার কৌশলকে তারল্য বনাম মুনাফা নীতি বলে। নগদ টাকা বেশি জমা রাখলে ব্যবসায় দৈনন্দিন দেনা মেটানো সহজ হয় কিন্তু কোনো মুনাফা হয় না; আবার সব টাকা বিনিয়োগ করলে মুনাফা বেশি হলেও দৈনন্দিন খরচ মেটানোর তারল্য সংকট দেখা দেয়। তাই আর্থিক ব্যবস্থাপককে উভয়ের মধ্যে সুষম ভারসাম্য বজায় রাখতে হয়।

#### (গ) প্রয়োগমূলক উত্তর:
জনাব রফিকুল ইসলাম অর্থায়নের **''উপযুক্ততার নীতি'' (Principle of Suitability)** লঙ্ঘন করেছেন। 

উপযুক্ততার নীতি অনুসারে তহবিলের ধরন ও ব্যবহারের মধ্যকার সঠিক বনাম ভুল প্রয়োগের তুলনামূলক ছক:

| ব্যয়ের ধরন | অর্থায়নের উপযুক্ত উৎস | জনাব রফিকুলের গৃহীত পদক্ষেপ | ফলাফল ও প্রভাব |
| :--- | :--- | :--- | :--- |
| **চলতি ব্যয়** (কাঁচামাল, মজুরি) | স্বল্পমেয়াদী উৎস (বাণিজ্যিক ব্যাংক চলতি ঋণ, পাওনাদার) | মূলধন শূন্য হয়ে তারল্য সংকট | কাঁচামাল ও মজুরি প্রদান ব্যাহত |
| **স্থায়ী সম্পদ** (ভারী যন্ত্রপাতি, জমি) | দীর্ঘমেয়াদী উৎস (মালিকের মূলধন, শেয়ার, দীর্ঘমেয়াদী ঋণ) | স্বল্পমেয়াদী চলতি ঋণ ব্যবহার করেছেন | দ্রুত ঋণ পরিশোধের মারাত্মক চাপ |

**বিশ্লেষণ:** জনাব রফিকুল ব্যাংকের স্বল্পমেয়াদী চলতি ঋণ দিয়ে দীর্ঘমেয়াদী যন্ত্রপাতি ক্রয় করায় ঋণের টাকা দ্রুত ফেরত দেওয়ার তাগাদা তৈরি হয় এবং দৈনন্দিন পরিচালন ব্যয়ের তহবিল শূন্য হয়ে তীব্র তারল্য সংকটের সৃষ্টি হয়।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
জনাব রফিকুলের ক্ষতির সম্মুখীন হওয়ার মূল কারণ হলো **''ব্যবসায়ের বৈচিত্র্যায়ন ও ঝুঁকি বণ্টন নীতি'' (Principle of Diversification & Risk Sharing)** অনুসরণ না করা।

একটি পণ্যে বিনিয়োগ বনাম বহুমুখী পণ্যে বিনিয়োগের প্রভাব বিশ্লেষণ সারণি:

| বিবেচ্য বিষয় | জনাব রফিকুলের পদক্ষেপ (একক পণ্য) | বৈচিত্র্যায়ন নীতি অনুযায়ী পদক্ষেপ (বহুমুখী পণ্য) |
| :--- | :--- | :--- |
| **বিনিয়োগের ক্ষেত্র** | সম্পূর্ণ মূলধন একটিমাত্র প্লাস্টিক পণ্যে বিনিয়োগ | একাধিক ভিন্নধর্মী গৃহস্থালি প্লাস্টিক পণ্যে বিনিয়োগ |
| **বাজার চাহিদার প্রভাব** | ওই পণ্যের চাহিদা কমায় পুরো কারখানা ক্ষতিগ্রস্ত | একটি পণ্যের চাহিদা কমলেও অন্য পণ্যের বিক্রি বৃদ্ধি পেত |
| **ঝুঁকির মাত্রা** | সর্বোচ্চ ঝুঁকি (১০০% বিপর্যয়) | ঝুঁকি বণ্টন ও ঝুঁকি হ্রাস (Risk Hedging) |
| **চূড়ান্ত পরিণতি** | বিশাল আর্থিক ক্ষতি ও দেউলিয়াত্বের ঝুঁকি | সামগ্রিক মুনাফা ও স্থিতিশীল অস্তিত্ব রক্ষা |

**সিদ্ধান্ত:** "একঝুড়িতে সব ডিম রেখো না" — এই আর্থিক নীতিটি না মেনে একক পণ্যে সব মূলধন খাঁটানোই জনাব রফিকুলের আর্থিক বিপর্যয়ের মূল কারণ।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (তারল্য বনাম মুনাফা নীতি ও তহবিল বণ্টন)

### উদ্দীপক:
> মেঘনা টেক্সটাইলের আর্থিক ব্যবস্থাপক জনাব শামীম কারখানার দৈনন্দিন খরচ মেটানোর আশঙ্কায় ব্যাংকে এবং ক্যাশ বাক্সে প্রয়োজনের অতিরিক্ত নগদ টাকা অলস জমিয়ে রাখেন। ফলে বছর শেষে দেখা গেল প্রতিষ্ঠানটির তারল্য ঘাটতি হয়নি, কিন্তু পর্যাপ্ত লাভজনক বিনিয়োগের অভাবে মুনাফার হার প্রতিযোগীদের চেয়ে অনেক কমে গেছে। পরিচালনা পর্ষদের সভায় তিনি দ্রুত মুনাফা বৃদ্ধির জন্য সমস্ত অলস টাকা একটি দীর্ঘমেয়াদী অটোমেশন প্রকল্পে বিনিয়োগের প্রস্তাব দেন।

---

### প্রশ্নাবলি:
- **(ক)** আর্থিক ব্যবস্থাপকের দুটি মৌলিক সিদ্ধান্ত কী কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ব্যবসায় অর্থায়নে তহবিল বণ্টন সিদ্ধান্ত বলতে কী বোঝায়? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** জনাব শামীমের অতিরিক্ত নগদ টাকা অলস জমিয়ে রাখার সিদ্ধান্তটি অর্থায়নের কোন নীতির পরিপন্থী? ছকের সাহায্যে ব্যাখ্যা কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** সমস্ত নগদ টাকা দীর্ঘমেয়াদী প্রকল্পে বিনিয়োগ করার প্রস্তাবটি বাস্তবায়িত হলে কী ধরনের সংকট দেখা দিতে পারে? ছকভিত্তিক মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
আর্থিক ব্যবস্থাপকের দুটি মৌলিক সিদ্ধান্ত হলো: ১. অর্থায়ন সিদ্ধান্ত (Financing Decision) এবং ২. বিনিয়োগ সিদ্ধান্ত (Investment Decision)।

#### (খ) অনুধাবনমূলক উত্তর:
প্রতিষ্ঠান কর্তৃক অর্জিত নিট মুনাফার কত অংশ শেয়ারহোল্ডারদের মধ্যে লভ্যাংশ হিসেবে বণ্টন করা হবে এবং কত অংশ ব্যবসা সম্প্রসারণের জন্য সংরক্ষিত তহবিল হিসেবে রেখে দেওয়া হবে—তা নির্ধারণকে তহবিল বণ্টন সিদ্ধান্ত বলে।

#### (গ) প্রয়োগমূলক উত্তর:
জনাব শামীমের সিদ্ধান্তটি অর্থায়নের **''তারল্য বনাম মুনাফা নীতি'' (Liquidity vs Profitability Principle)**-র পরিপন্থী।

অতিরিক্ত তারল্য সংরক্ষণ বনাম ভারসাম্যপূর্ণ তারল্য ব্যবস্থাপনার তুলনামূলক সারণি:

| নির্দেশক | জনাব শামীমের বর্তমান অবস্থান (অতিরিক্ত তারল্য) | কাম্য তারল্য ব্যবস্থাপনা (Optimal Balance) |
| :--- | :--- | :--- |
| **নগদ সংরক্ষণের পরিমাণ** | প্রয়োজনের অতিরিক্ত নগদ অর্থ ব্যাংকে অলস ফেলে রাখা | প্রাক্কলিত চলতি খরচের সমান নগদ টাকা রাখা |
| **বিনিয়োগ ও আয়** | লাভজনক উৎপাদনশীল খাতে বিনিয়োগ থেকে বঞ্চিত | অতিরিক্ত উদ্বৃত্ত অর্থ লাভজনক প্রকল্পে বিনিয়োগ |
| **মুনাফার হার** | মুনাফার হার সর্বনিম্ন ও মূলধনের অপচয় | মুনাফা সর্বাধিকরণ ও শেয়ারহোল্ডারদের সন্তুষ্টি |
| **প্রতিষ্ঠানের অবস্থান** | বাজারে প্রতিযোগিতায় পিছিয়ে পড়া | আর্থিক সচ্ছলতা ও প্রবৃদ্ধি নিশ্চিত হওয়া |

**ব্যাখ্যা:** নগদ টাকা নিজে কোনো মুনাফা তৈরি করতে পারে না। অতিরিক্ত তারল্য অলস ফেলে রেখে জনাব শামীম মুনাফা অর্জনের সুযোগ হাতছাড়া করেছেন।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
সমস্ত নগদ অর্থ দীর্ঘমেয়াদী প্রকল্পে বিনিয়োগ করলে প্রতিষ্ঠানটি চরম **তারল্য সংকটে (Liquidity Crisis)** পড়বে।

তারল্য ও মুনাফার বিপরীতমুখী প্রভাব বিশ্লেষণ সারণি:

| আর্থিক অবস্থান | সম্ভাব্য মুনাফা | দৈনন্দিন দেনা পরিশোধ ক্ষমতা | দেউলিয়াত্বের ঝুঁকি |
| :--- | :---: | :---: | :---: |
| **সব টাকা অলস রাখা** | সর্বনিম্ন | সর্বোচ্চ (কোনো ঝুঁকি নেই) | শূন্য কিন্তু অলাভজনক |
| **সব টাকা দীর্ঘমেয়াদী প্রকল্পে বিনিয়োগ** | সর্বোচ্চ | শূন্য (নগদ টাকা নেই) | **মারাত্মক দেউলিয়া ঝুঁকি** |
| **কাম্য ভারসাম্য (সুপারিশকৃত)** | **সন্তোষজনক** | **নিরাপদ ও সুষম** | **সম্পূর্ণ ঝুঁকিমুক্ত** |

**চূড়ান্ত মূল্যায়ন:** যদি সব টাকা দীর্ঘমেয়াদে আটকে ফেলা হয়, তবে জরুরি কাঁচামাল ক্রয় ও শ্রমিকের বেতন বন্ধ হয়ে কারখানার উৎপাদন ব্যাহত হবে। অতএব জনাব শামীমকে দৈনন্দিন খরচের নিরাপত্তা রেখে শুধুমাত্র অতিরিক্ত উদ্বৃত্ত অংশটুকু বিনিয়োগের নীতি গ্রহণ করতে হবে।
', 3);

