    VALUES (v_chapter_id, 'অর্থায়নের মূল চালিকাশক্তি কোনটি?', 'What is the primary driving force of finance?', '["পরিকল্পনা প্রণয়ন", "তহবিল সংগ্রহ ও বিনিয়োগ", "বিজ্ঞাপন প্রদান", "শ্রমিক নিয়োগ"]'::jsonb, 1);
