    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ২য় অধ্যায়: অর্থায়নের উৎস (Sources of Finance)

---

### ২.১ অর্থায়নের উৎসের শ্রেণিবিভাগ (Classification of Sources)
ব্যবসায় অর্থায়নের তহবিলকে প্রধানত দুটি দৃষ্টিকোণ থেকে ভাগ করা হয়:
১. **মালিকানার ভিত্তিতে:** অভ্যন্তরীণ তহবিল ও বহিঃস্থ তহবিল।
২. **মেয়াদকালের ভিত্তিতে:** স্বল্পমেয়াদী, মধ্যমেয়াদী ও দীর্ঘমেয়াদী তহবিল।

---

### ২.২ অভ্যন্তরীণ তহবিল (Internal Sources)
ব্যবসায়ের মালিক কর্তৃক নিজস্ব মূলধন বা ব্যবসায়িক মুনাফার যে অংশ প্রতিষ্ঠানে রেখে দেওয়া হয়, তাকে অভ্যন্তরীণ তহবিল বলে।

#### ক. মালিকানাভিত্তিক অভ্যন্তরীণ উৎস:
- **মালিকের মূলধন:** ব্যবসা শুরু বা সম্প্রসারণের জন্য মালিকের নিজস্ব সঞ্চয়।
- **শেয়ার মূলধন:** যৌথ মূলধনী কোম্পানি সাধারণ ও অগ্রাধিকার শেয়ার বিক্রির মাধ্যমে যে তহবিল গঠন করে।

#### খ. মুনাফাভিত্তিক অভ্যন্তরীণ উৎস:
- **অবণ্টিত মুনাফা ও সঞ্চিতি তহবিল:** অর্জিত মুনাফার যে অংশ লভ্যাংশ হিসেবে বণ্টন না করে ভবিষ্যতে সম্প্রসারণের জন্য রেখে দেওয়া হয়।
- **লভ্যাংশ সমতাকরণ তহবিল:** প্রতি বছর স্থিতিশীল লভ্যাংশ প্রদানের লক্ষ্যে গঠিত রিজার্ভ ফান্ড।
- **বিধিবদ্ধ সঞ্চিতি:** আইন অনুযায়ী ব্যাংকিং ও আর্থিক প্রতিষ্ঠান কর্তৃক বাধ্যতামূলকভাবে সংরক্ষিত তহবিল।

---

### ২.৩ বহিঃস্থ তহবিল (External Sources)
প্রতিষ্ঠানের বাইরের ব্যক্তি, ব্যাংক বা ঋণদাতা প্রতিষ্ঠান থেকে যে অর্থ সংগ্রহ করা হয় তাকে বহিঃস্থ তহবিল বলে।

| মেয়াদ | সময়কাল | প্রধান উৎসসমূহ |
| :--- | :--- | :--- |
| **স্বল্পমেয়াদী** | ১ বছর বা তার কম | ১. বাণিজ্যিক ঋণ (বাকিতে ক্রয়)<br>২. প্রাপ্য বিল বাট্টাকরণ<br>৩. ব্যাংক জমাতিরিক্ত উত্তোলন (Bank Overdraft - O/D)<br>৪. বাণিজ্যিক পত্র (Commercial Paper)<br>৫. ক্রেতার কাছ থেকে অগ্রিম গ্রহণ |
| **মধ্যমেয়াদী** | ১ বছর থেকে ৫ বছর | ১. বাণিজ্যিক ব্যাংক ঋণ<br>২. বিশেষায়িত আর্থিক প্রতিষ্ঠান (যেমন: বিডিবিএল, আইডিএলসি)<br>৩. বেসরকারি সংস্থা (NGO)<br>৪. মূলধনী যন্ত্রপাতি ভাড়ায় ক্রয় |
| **দীর্ঘমেয়াদী** | ৫ বছরের অধিক | ১. ঋণপত্র বা ডিবেঞ্চার (Debenture)<br>২. দীর্ঘমেয়াদী প্রাতিষ্ঠানিক ব্যাংক ঋণ<br>৩. লিজিং বা ইজারা (Leasing) |

---

### ২.৪ লিজিং (Leasing)
লিজিং দীর্ঘমেয়াদী অর্থায়নের একটি আধুনিক ও জনপ্রিয় বিকল্প পদ্ধতি। কোনো প্রতিষ্ঠান যদি অত্যন্ত ব্যয়বহুল আধুনিক যন্ত্রপাতি বা জমি সরাসরি ক্রয় না করে নির্দিষ্ট সময়ের জন্য ভাড়ার ভিত্তিতে ব্যবহার করে, তবে তাকে লিজিং বলে।
- **সুবিধা:** প্রাথমিক বিশাল মূলধনী ব্যয়ের চাপ থাকে না; আধুনিক প্রযুক্তির ব্যবহার নিশ্চিত হয়।
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (অভ্যন্তরীণ বনাম বহিঃস্থ ও ব্যবসায়িক ঋণ)

### উদ্দীপক:
> জনাব জামিল আহমেদ একটি টেক্সটাইল মিল স্থাপন করতে চান যার প্রাথমিক মূলধনী ব্যয় হবে প্রায় ১০ কোটি টাকা। তিনি নিজের জমাকৃত ২ কোটি টাকা এবং বন্ধুদের নিকট থেকে শেয়ারের মাধ্যমে ৩ কোটি টাকা সংগ্রহ করেন। বাকি ৫ কোটি টাকার জন্য তিনি বাণিজ্যিক ব্যাংক হতে ৭ বছর মেয়াদী দীর্ঘমেয়াদী ঋণ গ্রহণ করেন। অন্যদিকে মিলের সুতা ক্রয়ের জন্য তিনি স্থানীয় সরবরাহকারীর নিকট হতে ৬০ দিনের বাকিতে কাঁচামাল ক্রয়ের সুবিধা পান।

---

### প্রশ্নাবলি:
- **(ক)** লিজিং (Leasing) অর্থায়নের কোন ধরনের উৎস? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** বাণিজ্যিক পত্র বলতে কী বোঝায়? ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** জনাব জামিলের সংগৃহীত ১০ কোটি টাকার তহবিলের অভ্যন্তরীণ ও বহিঃস্থ উৎসগুলো ছকের মাধ্যমে চিহ্নিত ও শ্রেণিবিন্যাস কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** জনাব জামিলের ৬০ দিনের বাকিতে সুতা ক্রয়ের সিদ্ধান্তটি অর্থায়নের কোন উৎসের অন্তর্ভুক্ত? ছকভিত্তিক বিশ্লেষণের মাধ্যমে এর গুরুত্ব মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
লিজিং (Leasing) হলো বহিঃস্থ অর্থায়নের একটি আধুনিক দীর্ঘমেয়াদী বা মধ্যমেয়াদী অর্থায়নের উৎস।

#### (খ) অনুধাবনমূলক উত্তর:
প্রতিষ্ঠিত ও সুপরিচিত ব্যবসায় প্রতিষ্ঠানগুলো কোনো জামানত ছাড়া স্বল্পমেয়াদে অর্থ সংগ্রহের উদ্দেশ্যে যে স্বীকৃত প্রতিশ্রুতিপত্র বা অঙ্গীকারপত্র বাজারে বিক্রি করে, তাকে বাণিজ্যিক পত্র (Commercial Paper) বলে। এটি মূলত একটি অনিরাপদ স্বল্পমেয়াদী ঋণ দলিল যা বাট্টায় বিক্রি হয়।

#### (গ) প্রয়োগমূলক উত্তর:
জনাব জামিল আহমেদের মোট ১০ কোটি টাকার তহবিলের বিভাজন ও শ্রেণিবিভাগ সারণি:

| তহবিলের উৎস | ধরন | মেয়াদকাল | পরিমাণ (টাকা) | শতকরা অংশ (%) |
| :--- | :--- | :--- | :---: | :---: |
| **মালিকের নিজস্ব সঞ্চয়** | অভ্যন্তরীণ (মালিকানাধীনে) | দীর্ঘমেয়াদী | ২,০০,০০,০০০ | ২০% |
| **শেয়ার মূলধন (বন্ধুদের অংশ)** | অভ্যন্তরীণ (মালিকানাধীনে) | দীর্ঘমেয়াদী | ৩,০০,০০,০০০ | ৩০% |
| **বাণিজ্যিক ব্যাংক ঋণ** | বহিঃস্থ (প্রাতিষ্ঠানিক ঋণ) | দীর্ঘমেয়াদী (৭ বছর) | ৫,০০,০০,০০০ | ৫০% |
| **মোট তহবিল** | | | **১০,০০,০০,০০০** | **১০০%** |

**পর্যবেক্ষণ:** জামিল সাহেবের মূলধনের ৫০% অভ্যন্তরীণ মালিকানা তহবিল এবং ৫০% বহিঃস্থ ঋণ তহবিল দ্বারা গঠিত হয়েছে।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
জনাব জামিলের ৬০ দিনের বাকিতে সুতা ক্রয়ের সিদ্ধান্তটি **''ব্যবসায়িক ঋণ'' (Trade Credit)**-এর অন্তর্ভুক্ত, যা স্বল্পমেয়াদী বহিঃস্থ তহবিলের একটি স্বতঃস্ফূর্ত উৎস (Spontaneous Source of Finance)।

ব্যবসায়িক ঋণের গুরুত্ব ও প্রভাব সারণি:

| উপাদান | ব্যবসায়িক ঋণের সুবিধা | সাধারণ ব্যাংক ঋণের সাথে তুলনা |
| :--- | :--- | :--- |
| **সুদের চাপ** | কোনো সুদের হার নেই (বিনাসুদে অর্থায়ন) | ব্যাংক ঋণে নির্দিষ্ট হারে সুদ দিতে হয় |
| **জামানত** | কোনো স্থাবর সম্পত্তি জামানত দিতে হয় না | বাধ্যতামূলক জামানতের প্রয়োজন হয় |
| **তারল্য রক্ষা** | তাৎক্ষণিক নগদ অর্থের সংকট ছাড়াই উৎপাদন সচল থাকে | নগদ পরিশোধে চলতি মূলধন হ্রাস পায় |
| **পরিশোধ চক্র** | ৬০ দিনে উৎপাদিত কাপড় বিক্রি করে দেনা শোধ সম্ভব | প্রতি মাসে কিস্তি পরিশোধের বাধ্যবাধকতা থাকে |

**মূল্যায়ন:** এই স্বতঃস্ফূর্ত অর্থায়নের মাধ্যমে প্রতিষ্ঠানটি নগদ অর্থ না থাকা সত্ত্বেও স্বাভাবিক উৎপাদন চক্র চালু রাখতে সমর্থ হবে, যা টেক্সটাইল মিলের চলতি মূলধন ব্যবস্থাপনায় একটি অত্যন্ত বুদ্ধিদীপ্ত সিদ্ধান্ত।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (বাণিজ্যিক পত্র বনাম লিজিং/ইজারা অর্থায়ন)

### উদ্দীপক:
> সোনালী এগ্রো ফুডস লিমিটেড তাদের আধুনিক জুস প্রসেসিং প্ল্যান্টের জন্য ১ কোটি টাকা মূল্যের একটি অত্যাধুনিক জার্মান মেশিন সংগ্রহ করতে চায়। কিন্তু কোম্পানির কাছে এককালীন এত নগদ টাকা নেই। আর্থিক উপদেষ্টা দুটি বিকল্প উপস্থাপন করেন: বিকল্প-১: বাজারে ৯ মাস মেয়াদী বাণিজ্যিক পত্র (Commercial Paper) ইস্যু করে অর্থ সংগ্রহ করা; বিকল্প-২: একটি লিজিং কোম্পানির সাথে ৫ বছরের জন্য মেশিনটি ইজারার (Lease) চুক্তি করা যাতে প্রতি বছর ২০ লক্ষ টাকা ভাড়া দিয়ে মেশিনটি চালানো যাবে।

---

### প্রশ্নাবলি:
- **(ক)** স্বল্পমেয়াদী অর্থায়নের অপ্রাতিষ্ঠানিক উৎস কোনটি? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ব্যাংক জমাতিরিক্ত উত্তোলন (Bank Overdraft) কী? ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** সোনালী এগ্রো ফুডসের জন্য বাণিজ্যিক পত্র ইস্যুর মাধ্যমে মেশিন ক্রয়ের পরিকল্পনাটি উপযুক্ততার নীতির আলোকে ছকের সাহায্যে বিশ্লেষণ কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** বিকল্প-১ বনাম বিকল্প-২ (লিজিং)-এর সুবিধা ও অসুবিধার একটি তুলনামূলক সারণি তৈরি করে কোম্পানির জন্য কোনটি অধিক সুবিধাজনক সিদ্ধান্ত দাও। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
স্বল্পমেয়াদী অর্থায়নের একটি অন্যতম জনপ্রিয় অপ্রাতিষ্ঠানিক উৎস হলো গ্রাম্য মহাজন বা আত্মীয়স্বজনের নিকট থেকে ঋণ গ্রহণ।

#### (খ) অনুধাবনমূলক উত্তর:
বাণিজ্যিক ব্যাংক কর্তৃক তার বিশ্বস্ত চলতি হিসাবের আমানতকারীকে হিসাবে জমাকৃত টাকার পরিমাণের চেয়ে অতিরিক্ত অর্থ উত্তোলনের যে বিশেষ ঋণ সুবিধা দেওয়া হয়, তাকে ব্যাংক জমাতিরিক্ত উত্তোলন বা ওভারড্রাফট (Bank Overdraft - O/D) বলে।

#### (গ) প্রয়োগমূলক উত্তর:
বাণিজ্যিক পত্র দিয়ে স্থায়ী মেশিন ক্রয়ের পরিকল্পনা অর্থায়নের **উপযুক্ততার নীতি (Suitability)** পরিপন্থী।

উপযুক্ততার নীতি বিশ্লেষণ সারণি:

| আর্থিক উপাদান | বাণিজ্যিক পত্রের বৈশিষ্ট্য (বিকল্প-১) | স্থায়ী মেশিন ক্রয়ের চাহিদা | ফলাফলের অমিল |
| :--- | :--- | :--- | :--- |
| **মেয়াদকাল** | স্বল্পমেয়াদী (মাত্র ৯ মাস) | দীর্ঘমেয়াদী (আয়ুষ্কাল ৫-১০ বছর) | মাত্র ৯ মাসের মাথায় মূলধন ফেরত দিতে হবে |
| **নগদ প্রাপ্তি চক্র** | অতি দ্রুত পরিশোধের চাপ | মেশিন থেকে মুনাফা আসতে ২-৩ বছর সময় লাগে | মেয়াদ শেষে ঋণখেলাপি হওয়ার চরম ঝুঁকি |
| **উপযুক্ততা** | কাঁচামাল বা চলতি খরচ মেটানো | স্থায়ী সম্পত্তি অর্জন | **মারাত্মক আর্থিক অসমঞ্জস্যতা** |

**পর্যবেক্ষণ:** ৯ মাসের স্বল্পমেয়াদী বাণিজ্যিক পত্র দিয়ে দীর্ঘমেয়াদী মেশিন কেনার চেষ্টা করলে কোম্পানি ৯ মাস পর দেনা শোধ করতে ব্যর্থ হয়ে দেউলিয়া হয়ে যেতে পারে।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
বিকল্প-১ (বাণিজ্যিক পত্র) বনাম বিকল্প-২ (লিজিং)-এর তুলনামূলক সিদ্ধান্ত সারণি:

| মানদণ্ড | বিকল্প-১ (বাণিজ্যিক পত্র ইস্যু) | বিকল্প-২ (লিজিং বা ইজারা চুক্তি) |
| :--- | :--- | :--- |
| **প্রাথমিক মূলধন ব্যয়** | এককালীন ১ কোটি টাকার বিশাল চাপ | কোনো প্রাথমিক মূলধন লাগে না; শুধু বার্ষিক ভাড়া |
| **মেয়াদ ও পরিশোধ ঝুঁকি** | মাত্র ৯ মাসে পুরো টাকা পরিশোধের প্রচণ্ড চাপ | দীর্ঘ ৫ বছরে কিস্তিতে ভাড়া পরিশোধের স্বস্তি |
| **প্রযুক্তিগত ঝুঁকি** | মেশিন পুরনো বা অচল হলে পুরো লোকসান কোম্পানির | চুক্তি শেষে আধুনিক মডেলের নতুন মেশিনে আপগ্রেড সম্ভব |
| **রক্ষণাবেক্ষণ ও কর সুবিধা** | সব দায়ভার সোনালী এগ্রোর | ইজারা ভাড়া সম্পূর্ণ আয়কর রেয়াতযোগ্য খরচ |

**চূড়ান্ত সিদ্ধান্ত:** সোনালী এগ্রো ফুডস লিমিটেডের জন্য **''বিকল্প-২ (লিজিং/ইজারা)''** গ্রহণ করা সর্বোত্তম সিদ্ধান্ত। এতে প্রাথমিক নগদ মূলধনের চাপ ছাড়াই আধুনিক মেশিনে উৎপাদন শুরু করা যাবে।
