    VALUES (v_chapter_id, '# ৩য় অধ্যায়: অর্থের সময়মূল্য (Time Value of Money)

---

### ৩.১ অর্থের সময়মূল্যের ধারণা (Concept of Time Value of Money)
সময়ের পরিবর্তনের সাথে সাথে অর্থের মূল্যের যে পরিবর্তন ঘটে, তাকে অর্থের সময়মূল্য বলে। আজকের ১০০ টাকা আগামী এক বছর পরের ১০০ টাকার সমান নয়; আজকের ১০০ টাকা অধিক মূল্যবান। কারণ আজকের ১০০ টাকা ব্যাংকে বিনিয়োগ করলে নির্দিষ্ট সুদ পাওয়া যায়।

---

### ৩.২ সুযোগ ব্যয় ও ৭২ বিধি
- **সুযোগ ব্যয় (Opportunity Cost):** একটি প্রকল্পে অর্থ বিনিয়োগ করলে অন্য প্রকল্পের যে সম্ভাব্য আয় ছেড়ে দিতে হয়।
- **৭২ বিধি (Rule of 72):**

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>৭২ বিধি (টাকা দ্বিগুণ হওয়ার সময় নির্ণয়)</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    মেয়াদ (n) = <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">৭২</span><span class="pt-0.5 px-2 text-cyan-300">সুদের হার (i)</span></span> &nbsp;বা&nbsp; সুদের হার (i) = <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">৭২</span><span class="pt-0.5 px-2 text-cyan-300">বছর (n)</span></span>
  </div>
</div>

*উদাহরণ:* ৮% সুদে টাকা দ্বিগুণ হতে সময় লাগবে ৭২ ÷ ৮ = ৯ বছর।

---

### ৩.৩ ভবিষ্যৎ মূল্য (Future Value - FV) নির্ণয়ের সূত্র

#### ক. বার্ষিক একবার চক্রবৃদ্ধি হলে:

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>বার্ষিক চক্রবৃদ্ধি ভবিষ্যৎ মূল্য</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    FV = PV × (১ + i)ⁿ
  </div>
</div>

- **PV** = বর্তমান মূল্য (Present Value)
- **i** = বার্ষিক সুদের হার
- **n** = বছর বা মেয়াদের সংখ্যা

#### খ. বছরে একাধিকবার (m বার) চক্রবৃদ্ধি হলে:

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>বছরে একাধিকবার চক্রবৃদ্ধি ভবিষ্যৎ মূল্য</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    FV = PV × [১ + <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">i</span><span class="pt-0.5 px-2 text-cyan-300">m</span></span>]ⁿˣᵐ
  </div>
</div>

- **m** = বছরে চক্রবৃদ্ধির সংখ্যা:
  - অর্ধবার্ষিক (Semi-annually): m = ২
  - ত্রৈমাসিক (Quarterly): m = ৪
  - দ্বিমাসিক (Bi-monthly): m = ৬
  - মাসিক (Monthly): m = ১২
  - দৈনিক (Daily): m = ৩৬৫

---

### ৩.৪ বর্তমান মূল্য (Present Value - PV) বা বাট্টাকরণ

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>বার্ষিক বাট্টাকরণ বর্তমান মূল্য</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    PV = <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">FV</span><span class="pt-0.5 px-2 text-cyan-300">(১ + i)ⁿ</span></span>
  </div>
</div>


<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>বছরে একাধিকবার বাট্টাকরণ বর্তমান মূল্য</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    PV = <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">FV</span><span class="pt-0.5 px-2 text-cyan-300">[১ + <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">i</span><span class="pt-0.5 px-2 text-cyan-300">m</span></span>]ⁿˣᵐ</span></span>
  </div>
</div>


---

### ৩.৫ কার্যকর বার্ষিক সুদের হার (Effective Annual Rate - EAR)

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
