  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    EAR = [১ + <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">i</span><span class="pt-0.5 px-2 text-cyan-300">m</span></span>]ᵐ - ১
  </div>
