', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (বার্ষিক বনাম ত্রৈমাসিক চক্রবৃদ্ধি FV)

### উদ্দীপক:
> জনাব জামান অবসর গ্রহণের পর গ্র্যাচুইটি বাবদ এককালীন ১০,০০,০০০ টাকা পেলেন। তিনি এই অর্থ ৫ বছরের জন্য ব্যাংকে বিনিয়োগ করতে চান।
• ''যমুনা ব্যাংক'' তাকে বার্ষিক ১০% চক্রবৃদ্ধি সুদে বিনিয়োগের প্রস্তাব দিয়েছে।
• ''মেঘনা ব্যাংক'' তাকে ৯.৫% হারে ত্রৈমাসিক (বছরে ৪ বার) চক্রবৃদ্ধি সুদের প্রস্তাব দিয়েছে।

---

### প্রশ্নাবলি:
- **(ক)** সুযোগ ব্যয় (Opportunity Cost) কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ৭২ বিধি (Rule of 72) দ্বারা কী নির্ধারণ করা হয়? ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** যমুনা ব্যাংকের প্রস্তাব অনুযায়ী ৫ বছর পর জনাব জামান মোট কত টাকা পাবেন? সূত্রের সাহায্যে হিসাব কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** উভয় ব্যাংকের প্রাপ্ত ভবিষ্যৎ মূল্য ছকের মাধ্যমে তুলনা করে জনাব জামানের জন্য কোন ব্যাংকে বিনিয়োগ অধিক লাভজনক হবে সিদ্ধান্ত দাও। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
একটি নির্দিষ্ট প্রকল্পে অর্থ বিনিয়োগ করার ফলে অন্য আরেকটি বিকল্প প্রকল্পের সুযোগ বা লাভ পরিত্যাগ করতে হলে, সেই পরিত্যক্ত সুযোগের মূল্যকে সুযোগ ব্যয় (Opportunity Cost) বলে।

#### (খ) অনুধাবনমূলক উত্তর:
কোনো নির্দিষ্ট পরিমাণ অর্থ বার্ষিক কত শতাংশ সুদে অথবা কত বছরে দ্বিগুণ (Double) হবে, তা দ্রুত ও সহজে হিসাব করার জনপ্রিয় সংক্ষিপ্ত পদ্ধতিকে ৭২ বিধি বলে।
• মেয়াদ (n) = ৭২ / সুদের হার (i)
• সুদের হার (i) = ৭২ / বছর (n)

#### (গ) প্রয়োগমূলক উত্তর:
যমুনা ব্যাংকের ভবিষ্যৎ মূল্য (FV) নির্ণয়:

প্রদত্ত তথ্যের তালিকা:
- বর্তমান মূল্য (PV) = ১০,০০,০০০ টাকা
- বার্ষিক সুদের হার (i) = ১০% = ০.১০
- মেয়াদের বছর (n) = ৫ বছর

গাণিতিক সমাধান:
FV = PV × (১ + i)ⁿ
FV = ১০,০০,০০০ × (১ + ০.১০)⁵
FV = ১০,০০,০০০ × (১.১০)⁵ = ১০,০০,০০০ × ১.৬১০৫১
FV = ১৬,১০,৫১০ টাকা

**উত্তর:** ৫ বছর পর যমুনা ব্যাংক থেকে জনাব জামান মোট **১৬,১০,৫১০ টাকা** পাবেন।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
মেঘনা ব্যাংকের ভবিষ্যৎ মূল্য এবং উভয় ব্যাংকের তুলনামূলক বিশ্লেষণ সারণি:

**১. মেঘনা ব্যাংকের হিসাব (ত্রৈমাসিক চক্রবৃদ্ধি):**
- বর্তমান মূল্য (PV) = ১০,০০,০০০ টাকা
- সুদের হার (i) = ৯.৫% = ০.০৯৫
- বছরে চক্রবৃদ্ধির সংখ্যা (m) = ৪ (ত্রৈমাসিক)
- মেয়াদ (n) = ৫ বছর

FV = PV × [১ + (i / m)]ⁿᵐ
FV = ১০,০০,০০০ × [১ + (০.০৯৫ / ৪)]⁵ˣ⁴
FV = ১০,০০,০০০ × [১ + ০.০২৩৭৫]²⁰ = ১০,০০,০০০ × (১.০২৩৭৫)²⁰
FV = ১০,০০,০০০ × ১.৫৯৮৯৫ = ১৫,৯৮,৯৫০ টাকা

**২. তুলনামূলক সিদ্ধান্ত সারণি:**

| ব্যাংকের নাম | চক্রবৃদ্ধির ধরন | প্রযোজ্য সূত্র | ভবিষ্যৎ মূল্য (টাকা) | মুনাফার তারতম্য |
| :--- | :--- | :--- | :---: | :--- |
| **যমুনা ব্যাংক** | বার্ষিক একবার (m = ১) | FV = PV(1 + i)ⁿ | **১৬,১০,৫১০** | **১১,৫৬০ টাকা বেশি** |
| **মেঘনা ব্যাংক** | ত্রৈমাসিক (m = ৪) | FV = PV(1 + i/m)ⁿᵐ | **১৫,৯৮,৯৫০** | ১১,৫৬০ টাকা কম |

**চূড়ান্ত সিদ্ধান্ত:** যমুনা ব্যাংকে বিনিয়োগ করলে ৫ বছর পর মেঘনা ব্যাংকের চেয়ে ১১,৫৬০ টাকা বেশি পাওয়া যাবে। সুতরাং জনাব জামানের জন্য **''যমুনা ব্যাংক''**-এ অর্থ বিনিয়োগ করা অধিক লাভজনক হবে।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (বর্তমান মূল্য বাট্টাকরণ ও কার্যকর সুদের হার EAR)

### উদ্দীপক:
> জনাব শফিক ৫ বছর পর একটি নতুন প্রাইভেট কার কেনার জন্য ২০,০০,০০০ টাকা পেতে চান।\n• সুরমা ব্যাংক তাকে বার্ষিক ৯% সরল সুদে টাকা জমার প্রস্তাব করেছে।\n• রূপালী ব্যাংক তাকে ৮.৫% হারে মাসিক (বছরে ১২ বার) চক্রবৃদ্ধি সুদের প্রস্তাব দিয়েছে।\nতিনি জানতে চান বর্তমানে কোন ব্যাংকে কত টাকা জমা রাখতে হবে এবং রূপালী ব্যাংকের প্রকৃত কার্যকর সুদের হার (EAR) কত।

---

### প্রশ্নাবলি:
- **(ক)** কার্যকর বার্ষিক সুদের হার (EAR)-এর পূর্ণরূপ কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** বাট্টাকরণ প্রক্রিয়াকে চক্রবৃদ্ধিকরণের বিপরীত প্রক্রিয়া বলা হয় কেন? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** সুরমা ব্যাংকের প্রস্তাব অনুযায়ী ২০,০০,০০০ টাকা পাওয়ার জন্য জনাব শফিককে বর্তমানে কত টাকা জমা রাখতে হবে? নির্ণয় কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** রূপালী ব্যাংকের কার্যকর বার্ষিক সুদের হার (EAR) নির্ণয় কর এবং উভয় ব্যাংকের বর্তমান মূল্যের ছকভিত্তিক তুলনার মাধ্যমে শফিকের জন্য কোনটি সুবিধাজনক সিদ্ধান্ত দাও। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
EAR-এর পূর্ণরূপ হলো Effective Annual Rate (কার্যকর বার্ষিক সুদের হার)।

#### (খ) অনুধাবনমূলক উত্তর:
চক্রবৃদ্ধিকরণ পদ্ধতিতে বর্তমান মূল্যকে ভবিষ্যৎ মূল্যে রূপান্তরিত করা হয় (টাকার পরিমাণ বাড়ে); অপরদিকে বাট্টাকরণ পদ্ধতিতে ভবিষ্যৎ মূল্যের ওপর সুদের হার বাদ দিয়ে বর্তমান মূল্য নির্ধারণ করা হয় (টাকার পরিমাণ কমে)। তাই বাট্টাকরণ প্রক্রিয়াকে চক্রবৃদ্ধিকরণের বিপরীত প্রক্রিয়া বলা হয়।

#### (গ) প্রয়োগমূলক উত্তর:
সুরমা ব্যাংকে প্রয়োজনীয় বর্তমান মূল্য (PV) নির্ণয়:

প্রদত্ত তথ্যাবলি:
- ভবিষ্যৎ মূল্য (FV) = ২০,০০,০০০ টাকা
- বার্ষিক সুদের হার (i) = ৯% = ০.০৯
- মেয়াদ (n) = ৫ বছর

সূত্র:
PV = FV / (১ + i)ⁿ
PV = ২০,০০,০০০ / (১ + ০.০৯)⁵ = ২০,০০,০০০ / (১.০৯)⁵
PV = ২০,০০,০০০ / ১.৫৩৮৬২ = ১২,৯৯,৮৬৬ টাকা (প্রায়)

**উত্তর:** ৫ বছর পর ২০ লক্ষ টাকা পেতে হলে সুরমা ব্যাংকে আজ **১২,৯৯,৮৬৬ টাকা** জমা রাখতে হবে।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
রূপালী ব্যাংকের EAR ও উভয় ব্যাংকের তুলনামূলক বিশ্লেষণ সারণি:

**১. রূপালী ব্যাংকের কার্যকর বার্ষিক সুদের হার (EAR):**
এখানে, i = ৮.৫% = ০.০৮৫, m = ১২ (মাসিক)
EAR = [১ + (i / m)]ᵐ - ১
EAR = [১ + (০.০৮৫ / ১২)]¹² - ১ = [১ + ০.০০৭০৮৩]¹² - ১
EAR = (১.০০৭০৮৩)¹² - ১ = ১.০৮৮৩৯ - ১ = ০.০৮৮৩৯ বা **৮.৮৪%**

**২. রূপালী ব্যাংকের প্রয়োজনীয় বর্তমান মূল্য (PV):**
PV = FV / [১ + (i / m)]ⁿᵐ
PV = ২০,০০,০০০ / [১ + (০.০৮৫ / ১২)]⁵ˣ¹² = ২০,০০,০০০ / (১.০০৭০৮৩)⁶⁰
PV = ২০,০০,০০০ / ১.৫২৭৩ = ১৩,০৯,৪৯৪ টাকা

**৩. তুলনামূলক সিদ্ধান্ত সারণি:**

| ব্যাংকের নাম | সুদের হার ও ধরন | প্রয়োজনীয় বর্তমান আমানত | শফিকের লাভ / সাশ্রয় |
| :--- | :--- | :---: | :--- |
| **সুরমা ব্যাংক** | ৯.০০% (বার্ষিক) | **১২,৯৯,৮৬৬ টাকা** | **৯,৬২৮ টাকা কম জমা দিতে হবে** |
| **রূপালী ব্যাংক** | ৮.৫০% মাসিক (EAR = ৮.৮৪%) | ১৩,০৯,৪৯৪ টাকা | ৯,৬২৮ টাকা বেশি জমা দিতে হবে |

**সিদ্ধান্ত:** সুরমা ব্যাংকে কম টাকা জমা রেখেই ৫ বছর পর সমান ২০ লক্ষ টাকা পাওয়া যাবে। সুতরাং জনাব শফিকের জন্য **''সুরমা ব্যাংক''**-এ অর্থ বিনিয়োগ করা অধিক সাশ্রয়ী ও বুদ্ধিমানের কাজ হবে।
', 3);

