    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ৪র্থ অধ্যায়: ঝুঁকি ও অনিশ্চয়তা (Risk & Uncertainty)

---

### ৪.১ ঝুঁকি বনাম অনিশ্চয়তা (Risk vs Uncertainty)
- **অনিশ্চয়তা:** ভবিষ্যতে কী ঘটবে বা না ঘটবে তা নিশ্চিতভাবে জানা না থাকা। যেমন: আগামী বছর খরা হবে কি না। একে গাণিতিকভাবে পরিমাপ করা যায় না।
- **ঝুঁকি:** অনিশ্চয়তার যে অংশটুকু গাণিতিকভাবে পরিমাপ করা যায় এবং যা আর্থিক ক্ষতির কারণ হতে পারে, তাকে ঝুঁকি বলে।

---

### ৪.২ ঝুঁকির উৎসসমূহ (Sources of Risk)

#### ক. ব্যবসায় প্রতিষ্ঠানের দৃষ্টিকোণ থেকে:
1. **ব্যবসায়িক ঝুঁকি (Business Risk):** ব্যবসায়ের দৈনন্দিন পরিচালন ব্যয় (কাঁচামাল, বেতন, দোকান ভাড়া, বিদ্যুৎ বিল) পরিশোধে ব্যর্থ হওয়ার সম্ভাবনা।
2. **আর্থিক ঝুঁকি (Financial Risk):** ঋণ মূলধন ব্যবহারের ফলে নির্দিষ্ট মেয়াদে সুদ ও ঋণের কিস্তি পরিশোধে ব্যর্থ হওয়ার ঝুঁকি। ঋণ বেশি হলে আর্থিক ঝুঁকি বাড়ে।

#### খ. বিনিয়োগকারীর দৃষ্টিকোণ থেকে:
1. **সুদের হারের ঝুঁকি (Interest Rate Risk):** বাজারে সুদের হার পরিবর্তনের ফলে বিনিয়োগের (বন্ড বা ডিবেঞ্চার) বাজারমূল্য হ্রাস পাওয়ার ঝুঁকি।
2. **তারল্য ঝুঁকি (Liquidity Risk):** বিনিয়োগকৃত সম্পদ দ্রুত ও যুক্তিযুক্ত মূল্যে নগদে রূপান্তর করতে না পারার ঝুঁকি।

---

### ৪.৩ আদর্শ বিচ্যুতি (Standard Deviation) নির্ণয়
আদর্শ বিচ্যুতি হলো ঝুঁকি পরিমাপের একটি অন্যতম প্রধান পরিসাংখ্যিক পদ্ধতি।

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>আদর্শ বিচ্যুতি (ঝুঁকি পরিমাপের সূত্র)</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    σ = √[<span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">∑(আয় - গড় আয়)²</span><span class="pt-0.5 px-2 text-cyan-300">n - ১</span></span>]
  </div>
</div>


- **σ (সিগমা)** = আদর্শ বিচ্যুতি বা ঝুঁকির মাত্রা
- **n** = নমুনা বছরের সংখ্যা
- **সিদ্ধান্তের নিয়ম:** সমান গড় আয়ের ক্ষেত্রে যে প্রকল্পের আদর্শ বিচ্যুতি কম সেটি গ্রহণযোগ্য। আবার সমান ঝুঁকির ক্ষেত্রে যে প্রকল্পের গড় আয় বেশি সেটি গ্রহণযোগ্য।
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (প্রকল্প পদ্মা বনাম প্রকল্প মেঘনা আদর্শ বিচ্যুতি সারণি)

### উদ্দীপক:
> মেসার্স সুমনা এন্টারপ্রাইজের দুটি বিনিয়োগ প্রকল্প ''প্রকল্প পদ্মা'' ও ''প্রকল্প মেঘনা''-র বিগত ৪ বছরের আয়ের হার নিচে দেওয়া হলো:
• প্রকল্প পদ্মা: ২০১৬ সালে ২০%, ২০১৭ সালে ৫%, ২০১৮ সালে -৫% (ক্ষতি), ২০১৯ সালে ২০%
• প্রকল্প মেঘনা: ২০১৬ সালে ১৫%, ২০১৭ সালে ১০%, ২০১৮ সালে ১৫%, ২০১৯ সালে ২০%

---

### প্রশ্নাবলি:
- **(ক)** আর্থিক ঝুঁকি (Financial Risk) কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ঝুঁকি ও অনিশ্চয়তার মধ্যে পার্থক্য ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** ''প্রকল্প পদ্মা''-র আদর্শ বিচ্যুতি (Standard Deviation) ছকের মাধ্যমে নির্ণয় কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** উভয় প্রকল্পের আয় ও ঝুঁকি সারণির মাধ্যমে তুলনা করে মেসার্স সুমনা এন্টারপ্রাইজের জন্য কোন প্রকল্পটি গ্রহণযোগ্য মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
কোনো ব্যবসায় প্রতিষ্ঠান বহিঃস্থ উৎস থেকে ঋণ মূলধন সংগ্রহ করলে নির্দিষ্ট হারে সুদ ও ঋণের কিস্তি পরিশোধে ব্যর্থ হওয়ার যে শঙ্কা দেখা দেয়, তাকে আর্থিক ঝুঁকি বলে।

#### (খ) অনুধাবনমূলক উত্তর:
ভবিষ্যতে কোনো অপ্রত্যাশিত ঘটনা ঘটার সম্ভাবনা যার আর্থিক ক্ষতি পরিমাপ করা যায় এবং বীমা বা কৌশল দ্বারা হ্রাস করা যায়, তাকে ঝুঁকি বলে। অপরদিকে ভবিষ্যতের কোনো ঘটনা যার ফলাফল বা সম্ভাবনা কোনোভাবেই গাণিতিকভাবে পরিমাপ করা যায় না, তাকে অনিশ্চয়তা বলে। সকল ঝুঁকি অনিশ্চয়তা থেকে সৃষ্টি হয়, কিন্তু সব অনিশ্চয়তা ঝুঁকি নয়।

#### (গ) প্রয়োগমূলক উত্তর:
''প্রকল্প পদ্মা''-র বিগত ৪ বছরের আদর্শ বিচ্যুতি (σ) নির্ণয় সারণি:

১. মোট আয় = ২০% + ৫% + (-৫%) + ২০% = ৪০%
২. গড় আয় = ৪০% ÷ ৪ = ১০%

| বছর | আয় ($R_i$) | গড় আয় ($ar{R}$) | গড় থেকে ব্যবধান ($R_i - ar{R}$) | ব্যবধানের বর্গ $(R_i - ar{R})^2$ |
| :---: | :---: | :---: | :---: | :---: |
| ২০১৬ | ২০% | ১০% | ২০ - ১০ = ১০ | $(১০)^২ = ১০০$ |
| ২০১৭ | ৫% | ১০% | ৫ - ১০ = -৫ | $(-৫)^২ = ২৫$ |
| ২০১৮ | -৫% | ১০% | -৫ - ১০ = -১৫ | $(-১৫)^২ = ২২৫$ |
| ২০১৯ | ২০% | ১০% | ২০ - ১০ = ১০ | $(১০)^২ = ১০০$ |
| **মোট** | **৪০%** | | | **ব্যবধানের বর্গের যোগফল = ৪৫০** |

ব্যবধানের বর্গের গড় = ৪৫০ ÷ (৪ - ১) = ৪৫০ ÷ ৩ = ১৫০
আদর্শ বিচ্যুতি (σ) = √১৫০ = ১২.২৫%

**উত্তর:** প্রকল্প পদ্মার আদর্শ বিচ্যুতি (ঝুঁকির মাত্রা) হলো **১২.২৫%**।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
''প্রকল্প মেঘনা''-র আদর্শ বিচ্যুতি ও উভয় প্রকল্পের তুলনামূলক সিদ্ধান্ত সারণি:

**১. প্রকল্প মেঘনার আদর্শ বিচ্যুতি সারণি:**
- মোট আয় = ১৫% + ১০% + ১৫% + ২০% = ৬০%
- গড় আয় = ৬০% ÷ ৪ = ১৫%

| বছর | আয় ($R_i$) | গড় আয় ($ar{R}$) | গড় থেকে ব্যবধান ($R_i - ar{R}$) | ব্যবধানের বর্গ $(R_i - ar{R})^2$ |
| :---: | :---: | :---: | :---: | :---: |
| ২০১৬ | ১৫% | ১৫% | ১৫ - ১৫ = ০ | $(০)^২ = ০$ |
| ২০১৭ | ১০% | ১৫% | ১০ - ১৫ = -৫ | $(-৫)^২ = ২৫$ |
| ২০১৮ | ১৫% | ১৫% | ১৫ - ১৫ = ০ | $(০)^২ = ০$ |
| ২০১৯ | ২০% | ১৫% | ২০ - ১৫ = ৫ | $(৫)^২ = ২৫$ |
| **মোট** | **৬০%** | | | **যোগফল = ৫০** |

ব্যবধানের বর্গের গড় = ৫০ ÷ (৪ - ১) = ৫০ ÷ ৩ = ১৬.৬৭
আদর্শ বিচ্যুতি (σ) = √১৬.৬৭ = ৪.০৮%

**২. তুলনামূলক সিদ্ধান্ত সারণি:**

| প্রকল্প | গড় আয় | আদর্শ বিচ্যুতি (σ) | ঝুঁকির মাত্রা | বিনিয়োগ সিদ্ধান্ত |
| :--- | :---: | :---: | :---: | :--- |
| **প্রকল্প পদ্মা** | ১০% | ১২.২৫% | অত্যন্ত বেশি | বর্জনীয় |
| **প্রকল্প মেঘনা** | **১৫%** | **৪.০৮%** | **অত্যন্ত কম** | **গ্রহণযোগ্য (সর্বোত্তম)** |

**সিদ্ধান্ত:** প্রকল্প মেঘনার গড় আয় বেশি (১৫% > ১০%) এবং ঝুঁকি অনেক কম (৪.০৮% < ১২.২৫%)। সুতরাং মেসার্স সুমনা এন্টারপ্রাইজের জন্য **''প্রকল্প মেঘনা''** প্রকল্পটি নির্বাচন করা লাভজনক ও ঝুঁকিমুক্ত হবে।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (ব্যবসায়িক ঝুঁকি বনাম আর্থিক ঝুঁকি ও সুদের হারের ঝুঁকি)

### উদ্দীপক:
> শাপলা টেক্সটাইল তাদের মূলধনের ৬০% ব্যাংক ঋণের মাধ্যমে অর্থায়ন করেছে। সম্প্রতি বিদ্যুৎ বিল ও কাঁচামালের দাম বেড়ে যাওয়ায় তাদের পরিচালন ব্যয় বৃদ্ধি পেয়েছে। অপরদিকে বাজারে সুদের হার বৃদ্ধি পাওয়ায় ব্যাংকের ঋণের কিস্তির পরিমাণও বেড়ে গেছে। ফলে পর্যাপ্ত মুনাফা না হওয়ায় তারা ব্যাংক ঋণের কিস্তি দিতে হিমশিম খাচ্ছে। বিপরীতভাবে সুরমা টেক্সটাইল সম্পূর্ণ নিজস্ব মূলধনে প্রতিষ্ঠিত হওয়ায় তাদের ঋণের কোনো চাপ নেই।

---

### প্রশ্নাবলি:
- **(ক)** তারল্য ঝুঁকি কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** সুদের হারের ঝুঁকি কীভাবে বিনিয়োগকারীকে প্রভাবিত করে? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** শাপলা টেক্সটাইলের পরিচালন ব্যয় ও ব্যাংক ঋণের কিস্তি পরিশোধের ব্যর্থতার সম্ভাবনাকে কোন কোন ঝুঁকির সাথে তুলনা করা যায়? ছকের সাহায্যে ব্যাখ্যা কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** শাপলা টেক্সটাইল বনাম সুরমা টেক্সটাইলের মূলধন কাঠামো ও আর্থিক ঝুঁকির একটি তুলনামূলক সারণি তৈরি করে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
বিনিয়োগকারী বন্ড বা শেয়ার যুক্তিযুক্ত মূল্যে দ্রুত নগদে রূপান্তর করতে না পারার ঝুঁকিকে তারল্য ঝুঁকি বলে।

#### (খ) অনুধাবনমূলক উত্তর:
বাজারে যখন কেন্দ্রীয় ব্যাংক বা বাণিজ্যিক ব্যাংকে সুদের হার বৃদ্ধি পায়, তখন বিনিয়োগকারীদের কাছে পূর্বের কম সুদের বন্ড বা ডিবেঞ্চারের আকর্ষণ কমে যায় এবং বন্ডের বাজারমূল্য হ্রাস পায়। এর ফলে বিনিয়োগকারী মূলধনী ক্ষতির সম্মুখীন হন। একে সুদের হারের ঝুঁকি বলে।

#### (গ) প্রয়োগমূলক উত্তর:
শাপলা টেক্সটাইলের সম্মুখীন হওয়া ঝুঁকির বিভাজন সারণি:

| ব্যয়ের ক্ষেত্র ও সংকট | সংশ্লিষ্ট ঝুঁকির নাম | ঝুঁকি সৃষ্টির কারণ | প্রতিষ্ঠানের ওপর প্রভাব |
| :--- | :--- | :--- | :--- |
| **বিদ্যুৎ বিল ও কাঁচামালের মূল্য বৃদ্ধি** | **ব্যবসায়িক ঝুঁকি (Business Risk)** | দৈনন্দিন পরিচালন খরচ বিক্রয়লব্ধ আয় দিয়ে মেটাতে না পারা | পরিচালন মুনাফা শূন্যে নেমে আসা |
| **ঋণের কিস্তি ও সুদ পরিশোধের ব্যর্থতা** | **আর্থিক ঝুঁকি (Financial Risk)** | ৬০% মূলধন উচ্চ সুদে ব্যাংক ঋণ থেকে সংগ্রহ করা | ঋণখেলাপি হয়ে প্রতিষ্ঠান বন্ধের ঝুঁকি |

**ব্যাখ্যা:** পরিচালন খরচ মেটানোর অক্ষমতা ব্যবসায়িক ঝুঁকির জন্ম দেয় এবং অতিরিক্ত ঋণ ব্যবহারের ফলে আর্থিক ঝুঁকির সৃষ্টি হয়।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
শাপলা টেক্সটাইল বনাম সুরমা টেক্সটাইলের তুলনামূলক ঝুঁকি মূল্যায়ন সারণি:

| নির্দেশক | শাপলা টেক্সটাইল (৬০% ঋণ) | সুরমা টেক্সটাইল (১০০% নিজস্ব মূলধন) |
| :--- | :--- | :--- |
| **মূলধন কাঠামো** | ঋণ-নির্ভর আগ্রাসী মূলধন কাঠামো | সম্পূর্ণ সমতা বা ইকুইটি মূলধন কাঠামো |
| **স্থায়ী আর্থিক ব্যয়** | উচ্চ সুদের কিস্তি বাধ্যতামূলকভাবে প্রদেয় | কোনো সুদের কিস্তি বা নির্দিষ্ট দায় নেই |
| **মন্দার প্রভাব** | মন্দার সময় দেউলিয়া হওয়ার চরম ঝুঁকি থাকে | মন্দার সময়ও নিজস্ব মূলধনের জোরে টিকে থাকে |
| **সার্বিক ঝুঁকির মাত্রা** | **চরম আর্থিক ঝুঁকিপূর্ণ** | **সম্পূর্ণ আর্থিক ঝুঁকিমুক্ত** |

**চূড়ান্ত মূল্যায়ন:** শাপলা টেক্সটাইলের অতিরিক্ত ঋণ নির্ভরতা তাদের বিপদ ডেকে এনেছে। আর্থিক ঝুঁকি কমাতে তাদের উচিত ঋণের অনুপাত কমিয়ে নিজস্ব মূলধন বা নতুন শেয়ার ইস্যুর মাধ্যমে ঋণের বোঝা হ্রাস করা।
', 3);

