---

### ৫.১ মূলধন বাজেটিংয়ের ধারণা
মূলধন বাজেটিং হলো প্রতিষ্ঠানের দীর্ঘমেয়াদী বিনিয়োগ সিদ্ধান্তের মূল্যায়ন প্রক্রিয়া। স্থায়ী সম্পত্তি যেমন জমি, দালানকোঠা, কারখানা স্থাপন বা আধুনিক যন্ত্রপাতি ক্রয়ের মতো বড় অঙ্কের বিনিয়োগের সম্ভাব্য লাভজনকতা বিশ্লেষণের কৌশল এটি।

---

### ৫.২ প্রয়োগ ক্ষেত্র
১. নতুন ব্যবসা বা শিল্প কারখানা স্থাপন।
২. উৎপাদন ক্ষমতার সম্প্রসারণ।
৩. পুরাতন যন্ত্রপাতি প্রতিস্থাপন ও আধুনিকায়ন।
৪. নতুন পণ্য উদ্ভাবন ও বাজারজাতকরণ।

---

### ৫.৩ মূলধন বাজেটিংয়ের পদ্ধতিসমূহ

#### ১. গড় মুনাফার হার (Accounting Rate of Return - ARR)

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>গড় মুনাফার হার (ARR) সূত্র</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    ARR = <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">গড় নিট মুনাফা</span><span class="pt-0.5 px-2 text-cyan-300">গড় বিনিয়োগ</span></span> × ১০০%
  </div>
</div>

- **গড় নিট মুনাফা** = সব বছরের মোট কর-পরবর্তী নিট মুনাফা ÷ আয়ুষ্কাল (বছর)
- **গড় বিনিয়োগ** = (প্রাথমিক বিনিয়োগ + ভগ্নাংশ মূল্য) ÷ ২
- **সিদ্ধান্ত নীতি:** ARR যত বেশি হবে প্রকল্পটি তত গ্রহণযোগ্য।

#### ২. পে-ব্যাক সময় (Payback Period - PBP)
বিনিয়োগকৃত অর্থ কত দ্রুত নগদ প্রবাহের মাধ্যমে ফেরত আসবে তা নির্ণয় করার পদ্ধতি।

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>বার্ষিক নগদ প্রবাহ সমান হলে পে-ব্যাক সময়</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    PBP = <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">প্রাথমিক বিনিয়োগ</span><span class="pt-0.5 px-2 text-cyan-300">বার্ষিক নগদ আন্তঃপ্রবাহ</span></span>
  </div>
</div>


<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>নগদ আন্তঃপ্রবাহ (Cash Inflow) নির্ণয়</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    নগদ আন্তঃপ্রবাহ = কর-পরবর্তী নিট মুনাফা + বার্ষিক অবচয়
  </div>
</div>

