    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (রূপালী লিমিটেড প্যাকেজিং মেশিন: ARR ও Payback সারণি)

### উদ্দীপক:
> রূপালী লিমিটেড ৫,০০,০০০ টাকা মূল্যের একটি নতুন প্যাকেজিং মেশিন কেনার পরিকল্পনা করছে। মেশিনটির আয়ুষ্কাল ৪ বছর এবং ভগ্নাংশমূল্য শূন্য।
বিগত প্রাক্কলিত তথ্য:
• ১ম বছর: বিক্রয় ২,৫০,০০০ টাকা, চলতি খরচ ৫০,০০০ টাকা
• ২য় বছর: বিক্রয় ৩,০০,০০০ টাকা, চলতি খরচ ৬০,০০০ টাকা
• ৩য় বছর: বিক্রয় ৩,৫০,০০০ টাকা, চলতি খরচ ৭০,০০০ টাকা
• ৪র্থ বছর: বিক্রয় ৪,০০,০০০ টাকা, চলতি খরচ ৮০,০০০ টাকা
স্থায়ী খরচ প্রতি বছর ২০,০০০ টাকা, সরলরৈখিক অবচয় ধার্য করা হয় এবং করের হার ৩০%।

---

### প্রশ্নাবলি:
- **(ক)** বাট্টাকৃত পে-ব্যাক সময় কাকে বলে? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** মূলধন বাজেটিংকে বিনিয়োগের বাতিঘর বলা হয় কেন? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** মেশিনটির কর-পরবর্তী নিট মুনাফা ও গড় মুনাফার হার (ARR) ছকের মাধ্যমে নির্ণয় কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** মেশিনটির ক্রমযোজিত নগদ প্রবাহ সারণি তৈরি করে পে-ব্যাক সময় নির্ণয় কর এবং রূপালী লিমিটেডের বিনিয়োগ সিদ্ধান্ত মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
অর্থের সময়মূল্য বিবেচনায় নিয়ে নগদ প্রবাহ বাট্টাকরণের মাধ্যমে যে সময়কালে প্রাথমিক বিনিয়োগ উঠে আসে, তাকে বাট্টাকৃত পে-ব্যাক সময় বলে।

#### (খ) অনুধাবনমূলক উত্তর:
মূলধন বাজেটিং দীর্ঘমেয়াদী বিনিয়োগ সিদ্ধান্তের সাথে সম্পর্কিত। ভুল বিনিয়োগের কারণে প্রতিষ্ঠান দেউলিয়া হতে পারে। সঠিক প্রকল্প মূল্যায়ন করে লাভজনক বিনিয়োগ নিশ্চিত করার জন্য মূলধন বাজেটিং সঠিক পথ নির্দেশ করে বলে একে বিনিয়োগের বাতিঘর বলা হয়।

#### (গ) প্রয়োগমূলক উত্তর:
রূপালী লিমিটেডের মেশিনটির কর-পরবর্তী নিট মুনাফা ও ARR নির্ণয় সারণি:

**১. প্রাথমিক হিসাব:**
- প্রাথমিক বিনিয়োগ = ৫,০০,০০০ টাকা
- আয়ুষ্কাল = ৪ বছর
- বার্ষিক অবচয় = (৫,০০,০০০ - ০) ÷ ৪ = ১,২৫,০০০ টাকা প্রতি বছর।

**২. প্রাক্কলিত কর-পরবর্তী নিট মুনাফা বিবরণী সারণি:**

| বিবরণ | ১ম বছর (টাকা) | ২য় বছর (টাকা) | ৩য় বছর (টাকা) | ৪র্থ বছর (টাকা) |
| :--- | :---: | :---: | :---: | :---: |
| **বিক্রয়** | ২,৫০,০০০ | ৩,০০,০০০ | ৩,৫০,০০০ | ৪,০০,০০০ |
| (-) চলতি খরচ | (৫০,০০০) | (৬০,০০০) | (৭০,০০০) | (৮০,০০০) |
| (-) স্থায়ী খরচ | (২০,০০০) | (২০,০০০) | (২০,০০০) | (২০,০০০) |
| (-) অবচয় | (১,২৫,০০০) | (১,২৫,০০০) | (১,২৫,০০০) | (১,২৫,০০০) |
| **করপূর্ব মুনাফা (EBT)** | **৫৫,০০০** | **৯৫,০০০** | **১,৩৫,০০০** | **১,৭৫,০০০** |
| (-) কর (৩০%) | (১৬,৫০০) | (২৮,৫০০) | (৪০,৫০০) | (৫২,৫০০) |
| **কর-পরবর্তী নিট মুনাফা (EAT)** | **৩৮,৫০০** | **৬৬,৫০০** | **৯৪,৫০০** | **১,২২,৫০০** |

**৩. গড় মুনাফার হার (ARR) গণনা সারণি:**

| উপাদান | হিসাবের বিবরণ | পরিমাণ |
| :--- | :--- | :---: |
| **মোট নিট মুনাফা** | ৩৮,৫০০ + ৬৬,৫০০ + ৯৪,৫০০ + ১,২২,৫০০ | ৩,২২,০০০ টাকা |
| **গড় নিট মুনাফা** | ৩,২২,০০০ ÷ ৪ | ৮০,৫০০ টাকা |
| **গড় বিনিয়োগ** | (৫,০০,০০০ + ০) ÷ ২ | ২,৫০,০০০ টাকা |
| **গড় মুনাফার হার (ARR)** | (৮০,৫০০ ÷ ২,৫০,০০০) × ১০০% | **৩২.২%** |

**উত্তর:** মেশিনটির গড় মুনাফার হার (ARR) হলো **৩২.২%**।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
রূপালী লিমিটেডের মেশিনটির পে-ব্যাক সময় (Payback Period - PBP) নির্ণয় সারণি:

**১. ক্রমযোজিত নগদ আন্তঃপ্রবাহ সারণি:**
(নগদ আন্তঃপ্রবাহ = কর-পরবর্তী নিট মুনাফা + অবচয় ১,২৫,০০০ টাকা)

| বছর | কর-পরবর্তী নিট মুনাফা | অবচয় | নগদ আন্তঃপ্রবাহ | ক্রমযোজিত নগদ প্রবাহ ($CCF$) |
| :---: | :---: | :---: | :---: | :---: |
| **১ম** | ৩৮,৫০০ | ১,২৫,০০০ | ১,৬৩,৫০০ | ১,৬৩,৫০০ |
| **২য়** | ৬৬,৫০০ | ১,২৫,০০০ | ১,৯১,৫০০ | **৩,৫৫,০০০ ($C$)** |
| **৩য়** | ৯৪,৫০০ | ১,২৫,০০০ | **২,১৯,৫০০ ($D$)** | ৫,৭৪,৫০০ |
| **৪র্থ** | ১,২২,৫০০ | ১,২৫,০০০ | ২,৪৭,৫০০ | ৮,২২,০০০ |

**২. পে-ব্যাক সময় নির্ণয়:**
প্রাথমিক বিনিয়োগ = ৫,০০,০০০ টাকা (যা ২য় ও ৩য় বছরের মাঝামাঝি উঠে আসে)
- A = পূর্ণ বছর = ২ বছর
- NCO = প্রাথমিক বিনিয়োগ = ৫,০০,০০০ টাকা
- C = ২য় বছরের ক্রমযোজিত নগদ প্রবাহ = ৩,৫৫,০০০ টাকা
- D = ৩য় বছরের নগদ আন্তঃপ্রবাহ = ২,১৯,৫০০ টাকা

পে-ব্যাক সময় = A + [(NCO - C) ÷ D]
= ২ + [(৫,০০,০০০ - ৩,৫৫,০০০) ÷ ২,১৯,৫০০]
= ২ + [১,৪৫,০০০ ÷ ২,১৯,৫০০] = ২ + ০.৬৬ = ২.৬৬ বছর (২ বছর ৭ মাস ২৭ দিন)

**৩. সিদ্ধান্ত ও মূল্যায়ন সারণি:**

| মূল্যায়ন মানদণ্ড | প্রাক্কলিত ফলাফল | মন্তব্য ও সিদ্ধান্ত |
| :--- | :---: | :--- |
| **পে-ব্যাক সময়** | **২.৬৬ বছর** | আয়ুষ্কাল ৪ বছরের তুলনায় অনেক আগেই প্রাথমিক বিনিয়োগ ফেরত আসছে। |
| **গড় মুনাফার হার (ARR)** | **৩২.২%** | মূলধন খরচের চেয়ে অনেক বেশি লাভজনক। |

**চূড়ান্ত সিদ্ধান্ত:** মেশিনটির মাধ্যমে বিনিয়োগ দ্রুত ফেরত আসবে এবং উচ্চ মুনাফা নিশ্চিত হবে। অতএব রূপালী লিমিটেডের জন্য নতুন প্যাকেজিং মেশিনটি ক্রয় করার সিদ্ধান্ত সম্পূর্ণ লাভজনক ও গ্রহণযোগ্য।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (কর্ণফুলী এন্টারপ্রাইজ: ভগ্নাংশমূল্যসহ ARR ও অসম নগদ প্রবাহ)

### উদ্দীপক:
> কর্ণফুলী এন্টারপ্রাইজ তাদের কারখানায় ৬,০০,০০০ টাকা ব্যয়ে একটি নতুন প্রিন্টিং ইউনিট স্থাপনের সিদ্ধান্ত নিয়েছে। প্রকল্পটির আয়ুষ্কাল ৩ বছর এবং ৩ বছর শেষে ভগ্নাংশ মূল্য হবে ৬০,০০০ টাকা।\nপ্রকল্পের আগামী ৩ বছরের প্রাক্কলিত নিট মুনাফা যথাক্রমে: ১ম বছর ৮০,০০০ টাকা, ২য় বছর ১,০০,০০০ টাকা এবং ৩য় বছর ১,২০,০০০ টাকা। প্রতিষ্ঠানটির প্রত্যাশিত গড় মুনাফার হার (Cut-off rate) ২৫% এবং সর্বোচ্চ পে-ব্যাক সময় ২.৫ বছর।

---

### প্রশ্নাবলি:
- **(ক)** ভগ্নাংশ মূল্য (Salvage Value) কাকে বলে? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** পে-ব্যাক সময় পদ্ধতির প্রধান সীমাবদ্ধতা কী? ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** কর্ণফুলী এন্টারপ্রাইজের প্রিন্টিং ইউনিটটির গড় বিনিয়োগ ও গড় মুনাফার হার (ARR) ছকের মাধ্যমে নির্ণয় কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** প্রকল্পটির পে-ব্যাক সময় নির্ণয় কর এবং কোম্পানির নির্ধারিত মানদণ্ডের ভিত্তিতে প্রকল্পটি গ্রহণ করা উচিত কি না সারণিসহ যৌক্তিক মতামত দাও। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
স্থায়ী সম্পত্তির কার্যকাল বা আয়ুষ্কাল শেষে এর পরিত্যক্ত অংশ বা লোহালক্কড় বিক্রি করে যে সম্ভাব্য নগদ মূল্য পাওয়া যায়, তাকে ভগ্নাংশ মূল্য বা উদ্ধার মূল্য বলে।

#### (খ) অনুধাবনমূলক উত্তর:
পে-ব্যাক সময় পদ্ধতির প্রধান দুটি দুর্বলতা হলো: ১. এটি অর্থের সময়মূল্যকে সম্পূর্ণ উপেক্ষা করে (আজকের ১ টাকা আর ৩ বছর পরের ১ টাকাকে সমান মনে করে), এবং ২. পে-ব্যাক মেয়াদের পর যে নগদ আন্তঃপ্রবাহ ঘটে তা মোটেই বিবেচনা করে না।

#### (গ) প্রয়োগমূলক উত্তর:
কর্ণফুলী এন্টারপ্রাইজের গড় বিনিয়োগ ও ARR নির্ণয় সারণি:

**১. প্রাথমিক উপাদান তালিকা:**
- প্রাথমিক বিনিয়োগ = ৬,০০,০০০ টাকা
- ভগ্নাংশ মূল্য = ৬০,০০০ টাকা
- আয়ুষ্কাল = ৩ বছর

**২. ARR উপাদান সারণি:**

| উপাদান | সূত্র ও হিসাবের প্রক্রিয়া | ফলাফল |
| :--- | :--- | :---: |
| **মোট নিট মুনাফা** | ৮০,০০০ + ১,০০,০০০ + ১,২০,০০০ | ৩,০০,০০০ টাকা |
| **গড় নিট মুনাফা** | ৩,০০,০০০ ÷ ৩ | ১,০০,০০০ টাকা |
| **গড় বিনিয়োগ** | (প্রাথমিক বিনিয়োগ + ভগ্নাংশ মূল্য) ÷ ২ = (৬,০০,০০০ + ৬০,০০০) ÷ ২ | ৩,৩০,০০০ টাকা |
| **গড় মুনাফার হার (ARR)** | (গড় নিট মুনাফা ÷ গড় বিনিয়োগ) × ১০০% = (১,০০,০০০ ÷ ৩,৩০,০০০) × ১০০% | **৩০.৩%** |

**উত্তর:** প্রিন্টিং ইউনিটের গড় বিনিয়োগ ৩,৩০,০০০ টাকা এবং ARR হলো **৩০.৩%**।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
প্রকল্পের পে-ব্যাক সময় ও গ্রহণ-বর্জন সিদ্ধান্ত সারণি:

**১. বার্ষিক অবচয় নির্ণয়:**
বার্ষিক অবচয় = (প্রাথমিক বিনিয়োগ - ভগ্নাংশ মূল্য) ÷ আয়ুষ্কাল
= (৬,০০,০০০ - ৬০,০০০) ÷ ৩ = ৫,৪০,০০০ ÷ ৩ = ১,৮০,০০০ টাকা

**২. ক্রমযোজিত নগদ আন্তঃপ্রবাহ সারণি:**

| বছর | কর-পরবর্তী নিট মুনাফা | অবচয় | নগদ আন্তঃপ্রবাহ | ক্রমযোজিত নগদ প্রবাহ ($CCF$) |
| :---: | :---: | :---: | :---: | :---: |
| **১ম** | ৮০,০০০ | ১,৮০,০০০ | ২,৬০,০০০ | ২,৬০,০০০ |
| **২য়** | ১,০০,০০০ | ১,৮০,০০০ | ২,৮০,০০০ | **৫,৪০,০০০ ($C$)** |
| **৩য়** | ১,২০,০০০ | ১,৮০,০০০ + ৬০,০০০* | **৩,৬০,০০০ ($D$)** | ৯,০০,০০০ |

*(৩য় বছরে উদ্ধারকৃত ভগ্নাংশ মূল্য ৬০,০০০ টাকা নগদ আন্তঃপ্রবাহে যুক্ত হয়)*

**৩. পে-ব্যাক সময় হিসাব:**
বিনিয়োগ ৬,০০,০০০ টাকা ২য় ও ৩য় বছরের মাঝে উঠে আসে।
পে-ব্যাক সময় = ২ + [(৬,০০,০০০ - ৫,৪০,০০০) ÷ ৩,৬০,০০০] = ২ + (৬০,০০০ ÷ ৩,৬০,০০০) = ২ + ০.১৭ = **২.১৭ বছর** (২ বছর ২ মাস)

**৪. কোম্পানির মানদণ্ড বনাম অর্জিত ফলাফলের সিদ্ধান্ত সারণি:**

| মানদণ্ড | কোম্পানির লক্ষ্যমাত্রা | প্রকল্পের প্রকৃত ফলাফল | মূল্যায়ন |
| :--- | :---: | :---: | :--- |
| **গড় মুনাফার হার (ARR)** | সর্বনিম্ন ২৫% | **৩০.৩%** | লক্ষ্যমাত্রার চেয়ে ৫.৩% বেশি (সুপারিশযোগ্য) |
| **পে-ব্যাক সময় (PBP)** | সর্বোচ্চ ২.৫ বছর | **২.১৭ বছর** | নির্ধারিত মেয়াদের পূর্বেই টাকা উঠে আসছে |

**চূড়ান্ত সিদ্ধান্ত:** যেহেতু ARR কাট-অফ রেটের চেয়ে বেশি এবং পে-ব্যাক সময় লক্ষ্যমাত্রার চেয়ে কম, তাই কর্ণফুলী এন্টারপ্রাইজের প্রিন্টিং প্রকল্পটি গ্রহণ করা শতভাগ যুক্তিযুক্ত।
', 3);

