    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ৬ষ্ঠ অধ্যায়: মূলধন ব্যয় (Cost of Capital)

---

### ৬.১ মূলধন ব্যয়ের ধারণা
কোনো প্রতিষ্ঠান বিভিন্ন উৎস হতে মূলধন সংগ্রহ করার জন্য যে ব্যয় নির্বাহ করে বা বিনিয়োগকারীদের যে ন্যূনতম প্রতিদান দিতে বাধ্য থাকে, তাকে মূলধন ব্যয় বলে।

---

### ৬.২ বিভিন্ন উৎসের মূলধন ব্যয় নির্ণয়

#### ১. ব্যাংক ঋণ মূলধন ব্যয় (Cost of Debt - k_d):

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>কর সমন্বিত ঋণ মূলধন ব্যয়</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    k_d = R × (১ - t)
  </div>
</div>

- **R** = সুদের হার
- **t** = করের হার (Tax Rate)

#### ২. অগ্রাধিকার শেয়ারের ব্যয় (Cost of Preferred Stock - k_p):

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>অগ্রাধিকার শেয়ারের ব্যয়</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    k_p = <span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">D_p</span><span class="pt-0.5 px-2 text-cyan-300">P_0</span></span> × ১০০
  </div>
</div>

- **D_p** = অগ্রাধিকার শেয়ারের নির্দিষ্ট লভ্যাংশ
- **P_0** = শেয়ারের বাজার মূল্য বা ইস্যু মূল্য

#### ৩. সাধারণ শেয়ার মূলধন ব্যয় (Cost of Equity - k_e):

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>স্থির হারে লভ্যাংশ বৃদ্ধি মডেল</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    k_e = [<span class="inline-flex flex-col text-center align-middle mx-1.5 font-bold leading-tight"><span class="border-b-2 border-cyan-400 pb-0.5 px-2 text-cyan-200">D_1</span><span class="pt-0.5 px-2 text-cyan-300">P_0</span></span> + g] × ১০০
  </div>
</div>

- **D_1** = আগামী বছরের প্রত্যাশিত লভ্যাংশ
- **P_0** = বর্তমান শেয়ারের বাজারমূল্য
- **g** = লভ্যাংশ বৃদ্ধির হার (Growth rate)

---

### ৬.৩ ভারযুক্ত গড় মূলধন ব্যয় (Weighted Average Cost of Capital - WACC)

<div class="formula-card my-5 p-4 sm:p-5 rounded-2xl bg-gradient-to-r from-slate-900 via-indigo-950/50 to-slate-900 border border-indigo-500/40 text-center shadow-xl">
  <div class="text-xs font-black text-indigo-400 uppercase tracking-wider mb-2 flex items-center justify-center gap-1.5">
    <span>📐 সূত্র</span>
    <span>•</span>
    <span>ভারযুক্ত গড় মূলধন ব্যয় (WACC)</span>
  </div>
  <div class="text-base sm:text-xl font-bold text-white flex items-center justify-center gap-2 flex-wrap leading-relaxed">
    WACC = (w_d × k_d) + (w_p × k_p) + (w_e × k_e) + (w_r × k_r)
  </div>
</div>

- **w** = মোট মূলধনে প্রতিটি উৎসের অনুপাত বা ভার
- **k** = প্রতিটি উৎসের সুনির্দিষ্ট মূলধন ব্যয়
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (পদ্মা ট্রেডার্স: ৩ উৎসের WACC সারণি)

### উদ্দীপক:
> পদ্মা ট্রেডার্স লিমিটেডের মোট মূলধন ৪০,০০,০০০ টাকা। মূলধন কাঠামোর উপাদানসমূহ:
• ১০% ব্যাংক ঋণ: ১০,০০,০০০ টাকা (কর হার ৪০%)
• ৮% অগ্রাধিকার শেয়ার: ১০,০০,০০০ টাকা
• সাধারণ শেয়ার মূলধন: ২০,০০,০০০ টাকা (শেয়ারের বর্তমান বাজারমূল্য ১৫০ টাকা, প্রত্যাশিত লভ্যাংশ ১৫ টাকা এবং লভ্যাংশ বৃদ্ধির হার ৫%)

---

### প্রশ্নাবলি:
- **(ক)** মূলধন ব্যয় (Cost of Capital) কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ঋণ মূলধন ব্যয় হিসাব করার সময় কর সমন্বয় করতে হয় কেন? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** কোম্পানিটির সাধারণ শেয়ার মূলধনের ব্যয় সূত্র প্রয়োগ করে নির্ণয় কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** পদ্মা ট্রেডার্স লিমিটেডের ভারযুক্ত গড় মূলধন ব্যয় (WACC) একটি সুসংগঠিত সারণির মাধ্যমে নির্ণয় করে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
বিভিন্ন উৎস হতে সংগৃহীত তহবিলের ব্যবহার বাবদ তহবিল সরবরাহকারীদের যে ন্যূনতম প্রত্যাশিত আয়ের হার প্রদান করতে হয়, তাকে মূলধন ব্যয় বলে।

#### (খ) অনুধাবনমূলক উত্তর:
কোম্পানি যখন ঋণ মূলধনের ওপর সুদ প্রদান করে, তখন সেই সুদ করযোগ্য আয় থেকে পরিচালন খরচ হিসেবে বাদ দেওয়া যায়। ফলে করযোগ্য আয় হ্রাস পায় এবং কোম্পানি কর সুবিধাপ্রাপ্ত (Tax Shield) হয়। অর্থাৎ প্রকৃত ঋণের খরচ সুদের হারের চেয়ে কম হয়। তাই করের হার সমন্বয় করতে হয়।

#### (গ) প্রয়োগমূলক উত্তর:
সাধারণ শেয়ারের ব্যয় ($k_e$) নির্ণয় (স্থির বৃদ্ধি লভ্যাংশ মডেল):

প্রদত্ত তথ্যাবলি:
- বর্তমান বাজারমূল্য ($P_0$) = ১৫০ টাকা
- প্রত্যাশিত লভ্যাংশ ($D_1$) = ১৫ টাকা
- লভ্যাংশ বৃদ্ধির হার ($g$) = ৫% = ০.০৫

গাণিতিক সূত্র ও সমাধান:
k_e = [(D_1 / P_0) + g] × ১০০
k_e = [(১৫ / ১৫০) + ০.০৫] × ১০০ = (০.১০ + ০.০৫) × ১০০
k_e = ০.১৫ × ১০০ = ১৫%

**উত্তর:** পদ্মা ট্রেডার্স লিমিটেডের সাধারণ শেয়ারের ব্যয় হলো **১৫%**।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
পদ্মা ট্রেডার্স লিমিটেডের সার্বিক ভারযুক্ত গড় মূলধন ব্যয় (WACC) নির্ণয় সারণি:

**১. বিভিন্ন উৎসের নির্দিষ্ট ব্যয় নির্ণয়:**
- কর-সমন্বিত ঋণ ব্যয় ($k_d$) = R × (১ - t) = ১০% × (১ - ০.৪০) = ৬%
- অগ্রাধিকার শেয়ারের ব্যয় ($k_p$) = ৮%
- সাধারণ শেয়ার মূলধন ব্যয় ($k_e$) = ১৫%

**২. মূলধন কাঠামো ও WACC নির্ণয় সারণি:**

| মূলধনের উৎস | টাকার পরিমাণ | অনুপাত / ভার ($w$) | সুনির্দিষ্ট ব্যয় ($k$) | ভারযুক্ত ব্যয় ($w 	imes k$) |
| :--- | :---: | :---: | :---: | :---: |
| **ব্যাংক ঋণ (১০%)** | ১০,০০,০০০ | ১০,০০,০০০ / ৪০,০০,০০০ = ০.২৫ | ৬.০০% | ০.২৫ × ৬% = ১.৫০% |
| **৮% অগ্রাধিকার শেয়ার** | ১০,০০,০০০ | ১০,০০,০০০ / ৪০,০০,০০০ = ০.২৫ | ৮.০০% | ০.২৫ × ৮% = ২.০০% |
| **সাধারণ শেয়ার মূলধন** | ২০,০০,০০০ | ২০,০০,০০০ / ৪০,০০,০০০ = ০.৫০ | ১৫.০০% | ০.৫০ × ১৫% = ৭.৫০% |
| **মোট মূলধন** | **৪০,০০,০০০** | **১.০০** | | **WACC = ১১.০০%** |

**মূল্যায়ন ও সিদ্ধান্ত:** 
কোম্পানিটির সামগ্রিক ভারযুক্ত গড় মূলধন ব্যয় হলো **১১%**। এর অর্থ হলো, নতুন কোনো বিনিয়োগ প্রকল্পে বিনিয়োগ করতে হলে প্রতিষ্ঠানকে কমপক্ষে ১১% বা তার অধিক আয়ের হার নিশ্চিত করতে হবে; অন্যথায় প্রতিষ্ঠানটি মূলধনের খরচ মেটাতে ব্যর্থ হবে।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (মেঘনা ফুডস: সংরক্ষিত আয়সহ ৪ উপাদানের WACC সারণি)

### উদ্দীপক:
> মেঘনা ফুডস লিমিটেডের মোট পরিশোধিত মূলধন ৫০ লক্ষ টাকা। মূলধন কাঠামোর উপাদানসমূহ:\n• ১২% ঋণ মূলধন: ১০ লক্ষ টাকা (কর হার ৩০%)\n• ৯% অগ্রাধিকার শেয়ার: ১০ লক্ষ টাকা (বাজারমূল্য ১০০ টাকা)\n• সাধারণ শেয়ার মূলধন: ২০ লক্ষ টাকা (বাজারমূল্য ২০০ টাকা, চলতি বছর লভ্যাংশ ২০ টাকা, বৃদ্ধির হার ৪%)\n• সংরক্ষিত আয়: ১০ লক্ষ টাকা (সুযোগ ব্যয় ও ব্রোকারেজ ফি বিবেচনায় শেয়ারহোল্ডারদের প্রত্যাশিত আয় ১৪%)।

---

### প্রশ্নাবলি:
- **(ক)** সংরক্ষিত আয়ের ব্যয় বলতে কী বোঝায়? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** কোম্পানির জন্য ঋণ মূলধন ব্যয় ইকুইটি মূলধনের চেয়ে কম হয় কেন? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** মেঘনা ফুডস লিমিটেডের কর সমন্বিত ঋণ ব্যয় ও সাধারণ শেয়ারের ব্যয় নির্ণয় কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** প্রতিষ্ঠানটির ৪টি উপাদানের ভারযুক্ত গড় মূলধন ব্যয় (WACC) একটি সুসংবদ্ধ ছকের মাধ্যমে নির্ণয় করে সার্বিক বিনিয়োগ ঝুঁকি মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
অর্জিত নিট মুনাফার যে অংশ বণ্টন না করে কোম্পানিতে রেখে দেওয়া হয়, তার পেছনে শেয়ারহোল্ডারদের যে প্রত্যাশিত আয়ের সুযোগ ত্যাগ করতে হয়, তাকে সংরক্ষিত আয়ের ব্যয় (Cost of Retained Earnings) বলে।

#### (খ) অনুধাবনমূলক উত্তর:
ঋণ মূলধন ব্যয় কম হওয়ার দুটি কারণ: ১. ঋণের সুদের ওপর কর রেয়াত সুবিধা (Tax Shield) পাওয়া যায় যা খরচ কমিয়ে দেয়, এবং ২. ঋণগ্রহীতাদের নির্দিষ্ট সুদ দিতে হয় এবং জামানত থাকায় বিনিয়োগকারীদের ঝুঁকি কম থাকে, ফলে তারা কম মুনাফায় সন্তুষ্ট থাকে।

#### (গ) প্রয়োগমূলক উত্তর:
১. কর সমন্বিত ঋণ ব্যয় ($k_d$):
k_d = R × (১ - t) = ১২% × (১ - ০.৩০) = ১২% × ০.৭০ = ৮.৪০%

২. সাধারণ শেয়ার ব্যয় ($k_e$):
এখানে, D_0 = ২০ টাকা, g = ৪% = ০.০৪, P_0 = ২০০ টাকা
প্রত্যাশিত লভ্যাংশ (D_1) = D_0 × (১ + g) = ২০ × (১ + ০.০৪) = ২০.৮০ টাকা
k_e = [(D_1 / P_0) + g] × ১০০ = [(২০.৮০ / ২০০) + ০.০৪] × ১০০ = (০.১০৪ + ০.০৪) × ১০০ = ১৪.৪০%

**উত্তর:** কর সমন্বিত ঋণ ব্যয় **৮.৪০%** এবং সাধারণ শেয়ারের ব্যয় **১৪.৪০%**।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
মেঘনা ফুডস লিমিটেডের ৪ উপাদানের WACC নির্ণয় সারণি:

| মূলধনের উৎস | টাকার পরিমাণ | অনুপাত / ভার ($w$) | সুনির্দিষ্ট ব্যয় ($k$) | ভারযুক্ত ব্যয় ($w 	imes k$) |
| :--- | :---: | :---: | :---: | :---: |
| **১২% ঋণ মূলধন** | ১০,০০,০০০ | ১০ / ৫০ = ০.২০ | ৮.৪০% | ০.২০ × ৮.৪০% = ১.৬৮% |
| **৯% অগ্রাধিকার শেয়ার** | ১০,০০,০০০ | ১০ / ৫০ = ০.২০ | ৯.০০% | ০.২০ × ৯.০০% = ১.৮০% |
| **সাধারণ শেয়ার মূলধন** | ২০,০০,০০০ | ২০ / ৫০ = ০.৪০ | ১৪.৪০% | ০.৪০ × ১৪.৪০% = ৫.৭৬% |
| **সংরক্ষিত আয়** | ১০,০০,০০০ | ১০ / ৫০ = ০.২০ | ১৪.০০% | ০.২০ × ১৪.০০% = ২.৮০% |
| **মোট মূলধন** | **৫০,০০,০০০** | **১.০০** | | **WACC = ১২.০৪%** |

**বিনিয়োগ ঝুঁকি মূল্যায়ন:** মেঘনা ফুডসের ভারযুক্ত গড় মূলধন ব্যয় হলো **১২.০৪%**। ব্যবস্থাপনাকে নিশ্চিত করতে হবে যে নতুন গৃহীত যে কোনো কারখানার রিটার্ন যেন ১২.০৪% এর চেয়ে বেশি হয়, অন্যথায় শেয়ারের বাজারদর পড়ে যাবে এবং ব্যবসায় ক্ষতি হবে।
', 3);

