    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ৭ম অধ্যায়: শেয়ার, বন্ড ও ডিবেঞ্চার (Share, Bond & Debenture)

---

### ৭.১ শেয়ারের ধারণা ও প্রকারভেদ
যৌথ মূলধনী কোম্পানির মোট মূলধনকে ক্ষুদ্র ক্ষুদ্র সমান অংশে বিভক্ত করা হলে তার প্রতিটি একককে **শেয়ার (Share)** বলে।

1. **সাধারণ শেয়ার (Ordinary Share):** কোম্পানির প্রকৃত মালিকানা নির্দেশ করে। ভোটাধিকার থাকে কিন্তু লভ্যাংশ অনির্দিষ্ট।
2. **অগ্রাধিকার শেয়ার (Preference Share):** নির্দিষ্ট হারে লভ্যাংশ পান এবং মূলধন ফেরত পাওয়ার ক্ষেত্রে অগ্রাধিকার থাকে। কিন্তু ভোটাধিকার থাকে না।
3. **বোনাস শেয়ার (Bonus Share):** নগদ লভ্যাংশের বিকল্প হিসেবে জমাকৃত মুনাফার বিপরীতে বিদ্যমান শেয়ারহোল্ডারদের বিনামূল্যে প্রদত্ত শেয়ার।
4. **রাইট শেয়ার (Right Share):** কোম্পানি মূলধন বৃদ্ধির লক্ষ্যে নতুন শেয়ার ইস্যু করলে বিদ্যমান শেয়ারহোল্ডারদের অগ্রাধিকার ভিত্তিতে ক্রয়ের অধিকার প্রদান।

---

### ৭.২ বন্ড ও ডিবেঞ্চার
- **বন্ড (Bond):** দীর্ঘমেয়াদী ঋণের স্বীকৃতিপত্র যা সাধারণত সুনির্দিষ্ট স্থাবর সম্পত্তির জামানত সাপেক্ষে ইস্যু করা হয়।
- **ডিবেঞ্চার (Debenture):** কোনো সুনির্দিষ্ট জামানত ছাড়া শুধুমাত্র প্রতিষ্ঠানের সুনামের ভিত্তিতে ইস্যুকৃত দীর্ঘমেয়াদী ঋণ দলিল।
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (সাধারণ শেয়ার বনাম বন্ডের তুলনামূলক বিশ্লেষণ)

### উদ্দীপক:
> জনাব কামরুল ও জনাব তারেক দুজনেই পুঁজিলগ্নিকারী। জনাব কামরুল ঝুঁকি পছন্দ করেন এবং ব্যবস্থাপনায় ভোটাধিকার চান। তাই তিনি বিভিন্ন পাবলিক লিমিটেড কোম্পানির সাধারণ শেয়ারে বিনিয়োগ করেন। অন্যদিকে জনাব তারেক কোনো ঝুঁকি নিতে নারাজ এবং নির্দিষ্ট সময় পর পর জামানতযুক্ত স্থায়ী আয় ও মূলধনের পূর্ণ নিরাপত্তা নিশ্চিত করতে চান। তাই তিনি একটি শীর্ষস্থানীয় শিল্প গ্রুপের দীর্ঘমেয়াদী বন্ড ক্রয় করেন।

---

### প্রশ্নাবলি:
- **(ক)** রাইট শেয়ার (Right Share) কাকে বলে? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** বন্ড ও ডিবেঞ্চারের মধ্যে দুটি মূল পার্থক্য ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** জনাব কামরুল ও তারেকের পছন্দের ভিত্তিতে সাধারণ শেয়ার ও বন্ডের বৈশিষ্ট্যের একটি তুলনামূলক ছক প্রস্তুত কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** ঝুঁকি ও আয়ের দিক বিবেচনায় বিনিয়োগকারী হিসেবে দুজনের কৌশল ছকের মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
কোম্পানি মূলধন বৃদ্ধির জন্য নতুন শেয়ার ইস্যু করার সময় বিদ্যমান সাধারণ শেয়ারহোল্ডারদের অগ্রাধিকার ভিত্তিতে যে শেয়ার ক্রয়ের সুযোগ দেওয়া হয়, তাকে রাইট শেয়ার বলে।

#### (খ) অনুধাবনমূলক উত্তর:
১. জামানত: বন্ড সাধারণত কোম্পানির নির্দিষ্ট স্থাবর সম্পত্তির জামানতে ইস্যু করা হয়; কিন্তু ডিবেঞ্চার সম্পূর্ণ অনিরাপদ বা সাধারণ সুনামের ভিত্তিতে ইস্যু করা হয়।
২. ঝুঁকি: জামানত থাকার কারণে বন্ড ডিবেঞ্চারের তুলনায় অনেক কম ঝুঁকিপূর্ণ।

#### (গ) প্রয়োগমূলক উত্তর:
সাধারণ শেয়ার বনাম বন্ডের তুলনামূলক বৈশিষ্ট্য সারণি:

| তুলনার ভিত্তি | সাধারণ শেয়ার (জনাব কামরুল) | বন্ড (জনাব তারেক) |
| :--- | :--- | :--- |
| **মালিকানার স্বরূপ** | কোম্পানির প্রত্যক্ষ মালিকানা নির্দেশ করে | কোম্পানিকে প্রদত্ত দীর্ঘমেয়াদী ঋণ নির্দেশ করে |
| **আয়ের নিশ্চয়তা** | লভ্যাংশ অনির্দিষ্ট (লাভ বেশি হলে আয় বেশি) | নির্দিষ্ট হারে চুক্তিবদ্ধ সুদ পাওয়া যায় |
| **ভোটাধিকার** | পূর্ণ ভোটাধিকার থাকে এবং পরিচালক নির্বাচন করা যায় | কোনো ভোটাধিকার নেই |
| **নিরাপত্তা ও জামানত** | কোনো জামানত নেই, সর্বোচ্চ ঝুঁকি | কোম্পানির স্থাবর সম্পদ জামানত থাকে |
| **বিলোপসাধন অগ্রাধিকার** | সবার শেষে অবশিষ্ট তহবিল ফেরত পায় | সবার আগে মূলধন ফেরত পাওয়ার আইনগত অধিকার থাকে |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
জনাব কামরুল ও জনাব তারেকের বিনিয়োগ কৌশলের মূল্যায়ন সারণি:

| বিনিয়োগকারী | বিনিয়োগের মাধ্যম | বিনিয়োগকারীর ধরন (Investor Profile) | ঝুঁকি ও আয়ের অনুপাত (Risk-Return Tradeoff) |
| :--- | :--- | :--- | :--- |
| **জনাব কামরুল** | সাধারণ শেয়ার | ঝুঁকি গ্রহণকারী (Risk Seeker) | **উচ্চ ঝুঁকি ও উচ্চ আয়ের সম্ভাবনা:** পুঁজিবাজার চাঙা হলে মূলধনী লাভ (Capital Gain) ও লভ্যাংশ উভয়ই বেশি হবে। |
| **জনাব তারেক** | শিল্প বন্ড | ঝুঁকি পরিহারকারী (Risk Averse) | **কম ঝুঁকি ও নিশ্চিত আয়:** শেয়ারবাজারের ওঠানামা সত্ত্বেও মূলধনের ১০০% নিরাপত্তা ও নিয়মিত নির্দিষ্ট সুদ প্রাপ্তি নিশ্চিত। |

**উপসংহার:** উভয় বিনিয়োগকারীই তাদের নিজস্ব আর্থিক মানসিকতা ও লক্ষ্য অনুযায়ী সঠিক সম্পদ নির্বাচন করেছেন। কামরুলের কৌশল আগ্রাসী প্রবৃদ্ধির এবং তারেকের কৌশল সম্পদ সুরক্ষার জন্য যথোপযুক্ত।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (বোনাস শেয়ার, রাইট শেয়ার ও ডিবেঞ্চার পোর্টফোলিও)

### উদ্দীপক:
> মেঘনা ফার্মা লিমিটেড বাজারে নতুন অ্যান্টিবায়োটিক প্ল্যান্ট স্থাপনের জন্য মূলধন সংগ্রহ করতে চায়। পরিচালনা পর্ষদের সভায় ব্যবস্থাপনা পরিচালক বিদ্যমান শেয়ারহোল্ডারদের নগদ লভ্যাংশ না দিয়ে বিনামূল্যে বোনাস শেয়ার ইস্যুর প্রস্তাব করেন। অন্যদিকে অর্থ পরিচালক বিদ্যমান সাধারণ শেয়ারহোল্ডারদের নিকট থেকে মূলধন বাড়াতে রাইট শেয়ার এবং প্রতিষ্ঠানের দীর্ঘমেয়াদী সুনামের ওপর ভিত্তি করে জামানতহীন ডিবেঞ্চার বিক্রির পরামর্শ দেন।

---

### প্রশ্নাবলি:
- **(ক)** বোনাস শেয়ারের অপর নাম কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ডিবেঞ্চারকে অনিরাপদ ঋণপত্র বলা হয় কেন? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** বোনাস শেয়ার বনাম রাইট শেয়ারের মধ্যে তুলনামূলক পার্থক্যের একটি সারণি তৈরি কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** কোম্পানি এবং বিনিয়োগকারীর দৃষ্টিকোণ থেকে ডিবেঞ্চার ইস্যুর সুবিধা ও অসুবিধার একটি সমন্বিত ছক তৈরি করে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
বোনাস শেয়ারের অপর নাম হলো স্টক লভ্যাংশ (Stock Dividend)।

#### (খ) অনুধাবনমূলক উত্তর:
ডিবেঞ্চারের বিপরীতে কোম্পানির কোনো নির্দিষ্ট স্থাবর সম্পত্তি বা দলিল জামানত হিসেবে বন্ধক রাখা হয় না। এটি শুধুমাত্র কোম্পানির সাধারণ সুনাম ও অঙ্গীকারের ওপর নির্ভর করে বাজারে ছাড়া হয়। প্রতিষ্ঠান দেউলিয়া হলে সাধারণ পাওনাদারদের মতোই অনিশ্চয়তা থাকে বলে একে অনিরাপদ ঋণপত্র বলে।

#### (গ) প্রয়োগমূলক উত্তর:
বোনাস শেয়ার বনাম রাইট শেয়ারের তুলনামূলক সারণি:

| তুলনার মাপকাঠি | বোনাস শেয়ার (Stock Dividend) | রাইট শেয়ার (Right Share) |
| :--- | :--- | :--- |
| **মূল্য পরিশোধ** | শেয়ারহোল্ডারদের কোনো টাকা দিতে হয় না (বিনামূল্যে) | নির্দিষ্ট মূল্যে শেয়ারহোল্ডারকে টাকা দিয়ে কিনতে হয় |
| **তহবিলের উৎস** | কোম্পানির জমাকৃত অবণ্টিত মুনাফাকে মূলধনে রূপান্তর | শেয়ারহোল্ডারদের পকেট থেকে নতুন নগদ তহবিল সংগ্রহ |
| **নগদ অর্থের প্রবাহ** | কোম্পানিতে নতুন নগদ অর্থ আসে না | কোম্পানিতে বিপুল পরিমাণ নতুন নগদ অর্থ প্রবেশ করে |
| **উদ্দেশ্য** | নগদ লভ্যাংশ সংরক্ষণ করে ব্যবসায় পুনঃবিনিয়োগ | নতুন বৃহৎ কারখানা বা ব্যবসা সম্প্রসারণে তহবিল সংগ্রহ |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
ডিবেঞ্চার ইস্যুর সুবিধা ও অসুবিধা বিশ্লেষণ সারণি:

| পক্ষ | সুবিধা | অসুবিধা |
| :--- | :--- | :--- |
| **কোম্পানির দৃষ্টিকোণ থেকে** | কোনো স্থায়ী সম্পত্তি বন্ধক দিতে হয় না; পরিচালনায় নিয়ন্ত্রণ নষ্ট হয় না | লাভ বা ক্ষতি যাই হোক নির্দিষ্ট সুদ দিতেই হবে; সুনামে ঘাটতি হলে বিক্রি হয় না |
| **বিনিয়োগকারীর দৃষ্টিকোণ থেকে** | নিয়মিত নির্দিষ্ট হারে নিশ্চিত সুদ পাওয়া যায় | কোনো স্থাবর সম্পত্তির জামানত না থাকায় দেউলিয়া হলে টাকা হারানোর ভয় থাকে |

**চূড়ান্ত মতামত:** প্রতিষ্ঠিত ও সুনামধারী কোম্পানির জন্য ডিবেঞ্চার সম্পদ বন্ধক না রেখে ঋণ সংগ্রহের চমৎকার উপায় হলেও বিনিয়োগকারীদের জন্য এটি সাধারণ বন্ডের চেয়ে বেশি ঝুঁকিপূর্ণ।
', 3);

    INSERT INTO exam_questions (chapter_id, question_bn, question_en, options_json, correct_answer_index)
    VALUES (v_chapter_id, 'কোন ধরণের শেয়ারহোল্ডারগণ কোম্পানিতে ভোটাধিকার প্রয়োগের ক্ষমতা রাখেন?', 'Which shareholders hold voting rights in the company?', '["অগ্রাধিকার শেয়ারহোল্ডার", "সাধারণ শেয়ারহোল্ডার", "বিলম্বিত শেয়ারহোল্ডার", "বোনাস শেয়ারহোল্ডার"]'::jsonb, 1);
