    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ৮ম অধ্যায়: মুদ্রা, ব্যাংক ও ব্যাংকিং (Money, Bank & Banking)

---

### ৮.১ মুদ্রার ইতিহাস ও বিবর্তন
মানব সভ্যতার সূচনালগ্নে মানুষ দ্রব্যের বিনিময়ে দ্রব্য (Barter System) আদান-প্রদান করত। কিন্তু চাহিদার অমিল ও মূল্যের অসমতার কারণে মানুষ বিনিময়ের একটি সাধারণ মাধ্যম খুঁজতে শুরু করে।
1. **প্রথম পর্যায়:** হাতির দাঁত, কড়ি, পশুর চামড়া, পাথরের ব্যবহার।
2. **দ্বিতীয় পর্যায়:** তামা, ব্রোঞ্জ, রূপা ও স্বর্ণের ধাতব মুদ্রা।
3. **তৃতীয় পর্যায়:** কাগজের মুদ্রা ও চেক।
4. **আধুনিক পর্যায়:** প্লাস্টিক মানি (ডেবিট/ক্রেডিট কার্ড) ও ইলেকট্রনিক কারেন্সি (মোবাইল ও ইন্টারনেট ব্যাংকিং)।

---

### ৮.২ মুদ্রার কার্যাবলি
১. বিনিময়ের মাধ্যম (Medium of Exchange)
২. মূল্যের পরিমাপক (Measure of Value)
৩. সঞ্চয়ের ভাণ্ডার (Store of Value)
৪. স্থগিত লেনদেনের মানদণ্ড (Standard of Deferred Payments)

---

### ৮.৩ ব্যাংক ও ব্যাংকিংয়ের ধারণা
- **ব্যাংক:** একটি আর্থিক মধ্যস্থতাকারী প্রতিষ্ঠান যা স্বল্প সুদে জনসাধারণের অলস সঞ্চয় আমানত হিসেবে গ্রহণ করে এবং অধিক সুদে বিনিয়োগকারী ও ব্যবসায়ীদের ঋণ প্রদান করে।
- **ব্যাংকিং:** ব্যাংকের যাবতীয় আইনসম্মত কার্যক্রম ও সেবামূলক কাজের সমষ্টিকে ব্যাংকিং বলে।
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (বিনিময় প্রথা বনাম আধুনিক মুদ্রা ব্যবস্থা)

### উদ্দীপক:
> প্রাচীনকালে মানুষ যখন নিজেদের উৎপাদিত ধান দিয়ে অন্যের নিকট থেকে মাছ কিংবা তেলের বিনিময় করত, তখন প্রায়ই দুজনের প্রয়োজনের মিল হতো না। এই সমস্যা দূর করার জন্য কালক্রমে কড়ি, পাথর, তামা ও রূপার ব্যবহার শুরু হয়। পরবর্তীতে মূল্যবান ধাতুর বহনযোগ্যতার সীমাবদ্ধতা ও নিরাপত্তা সংকটের কারণে কাগজের মুদ্রা এবং আধুনিক ব্যাংক ব্যবস্থার জন্ম হয়।

---

### প্রশ্নাবলি:
- **(ক)** বিনিময় প্রথা (Barter System) কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** মুদ্রাকে সঞ্চয়ের ভাণ্ডার বলা হয় কেন? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** বিনিময় প্রথা বনাম আধুনিক মুদ্রা ব্যবস্থার বৈশিষ্ট্য ও সীমাবদ্ধতার একটি তুলনামূলক ছক প্রস্তুত কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** ''মুদ্রা ও ব্যাংক একে অপরের পরিপূরক'' — উক্তিটি ছকভিত্তিক বিশ্লেষণের মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
মুদ্রা আবিষ্কারের পূর্বে সরাসরি এক দ্রব্যের সাথে অন্য দ্রব্যের বিনিময় করার যে ব্যবস্থা চালু ছিল, তাকে পণ্য বিনিময় প্রথা বা বার্টার সিস্টেম (Barter System) বলে।

#### (খ) অনুধাবনমূলক উত্তর:
নশ্বর বা পচনশীল দ্রব্য (যেমন মাছ, শাকসবজি) দীর্ঘদিন জমিয়ে রাখা যায় না। কিন্তু সেগুলো বিক্রি করে মুদ্রায় রূপান্তর করলে তা দীর্ঘদিন যাবত মান ক্ষুণ্ন না করে জমিয়ে রাখা সম্ভব। এই জন্য মুদ্রাকে সঞ্চয়ের অন্যতম প্রধান ভাণ্ডার হিসেবে গণ্য করা হয়।

#### (গ) প্রয়োগমূলক উত্তর:
বিনিময় প্রথা বনাম আধুনিক মুদ্রা ব্যবস্থার তুলনামূলক সারণি:

| তুলনার ভিত্তি | প্রাচীন বিনিময় প্রথা (Barter System) | আধুনিক মুদ্রা ব্যবস্থা |
| :--- | :--- | :--- |
| **লেনদেনের মাধ্যম** | সরাসরি দ্রব্য বনাম দ্রব্য | সার্বজনীন গ্রহণযোগ্য কাগজের টাকা ও ধাতব কয়েন |
| **প্রয়োজনের মিল** | দ্বিমুখী মিল (Double Coincidence) বাধ্যতামূলক | কোনো মিলের প্রয়োজন নেই; সর্বজনস্বীকৃত |
| **বিভাজ্যতা** | অনেক দ্রব্য (যেমন গরু, নৌকা) ভাগ করা অসম্ভব | ক্ষুদ্র থেকে বৃহৎ এককে সহজেই বিভাজ্য |
| **বহনযোগ্যতা** | ভারী পণ্য বহন করা বিপজ্জনক ও কষ্টসাধ্য | সহজে মানিব্যাগে বা অনলাইনে বহনযোগ্য |
| **মূল্য পরিমাপ** | মূল্যের কোনো নির্দিষ্ট একক ছিল না | সুনির্দিষ্ট আর্থিক মূল্যমান রয়েছে (যেমন: ১০০ টাকা) |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
মুদ্রা ও ব্যাংকের পারস্পরিক নির্ভরশীলতা সারণি:

| প্রেক্ষাপট | ব্যাংকের ওপর মুদ্রার প্রভাব | মুদ্রার ওপর ব্যাংকের প্রভাব |
| :--- | :--- | :--- |
| **প্রধান উপাদান** | মুদ্রা ব্যাংকিং ব্যবসায়ের মূল কাঁচামাল; আমানত হিসেবে সংগৃহীত হয় | ব্যাংক মুদ্রার অলস অপচয় রোধ করে বিনিয়োগে রূপান্তর করে |
| **নিরাপত্তা** | নগদ টাকা ঘরে রাখার ঝুঁকি ব্যাংকে জমা দিয়ে দূর হয় | ব্যাংক লকার ও সিকিউরড ভল্টের মাধ্যমে মুদ্রার পূর্ণ নিরাপত্তা দেয় |
| **লেনদেন সহজীকরণ** | ভারী মুদ্রা টানার প্রয়োজন দূর করে ব্যাংক চেকবই চালু করেছে | অনলাইন ব্যাংকিং ও এটিএম কার্ডের মাধ্যমে নগদ টাকা বহন ছাড়াই লেনদেন নিশ্চিত হয় |

**উপসংহার:** মুদ্রা ছাড়া ব্যাংকের কোনো অস্তিত্ব থাকতে পারে না, আবার আধুনিক ব্যাংক ব্যবস্থা ছাড়া মুদ্রার গতিশীল সঞ্চালন ও নিরাপদ ব্যবহার অসম্ভব। অতএব মুদ্রা ও ব্যাংক একে অপরের অবিচ্ছেদ্য পরিপূরক।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (ধাতব মুদ্রা থেকে প্লাস্টিক মানি ও ডিজিটাল মুদ্রা বিবর্তন)

### উদ্দীপক:
> জনাব জামশেদ বিদেশে ভ্রমণের সময় একসময় স্বর্ণমুদ্রা ও শত শত ডলারের কাগজের নোট পকেটে নিয়ে ঘুরতেন, যা ছিনতাই ও ডাকাতির ভয় তৈরি করত। কিন্তু বর্তমানে তার ছেলে তানজিম বিদেশে পড়াশোনা করার সময় সাথে কোনো নগদ টাকা না রেখে একটি আন্তর্জাতিক ভিসা কার্ড এবং স্মার্টফোনে ব্যাংকিং অ্যাপ ব্যবহার করে নিমেষেই শপিং ও টিউশন ফি পরিশোধ করেন। তানজিম বলেন, ''ভবিষ্যতের বিশ্ব নগদহীন বা ক্যাশলেস সোসাইটির দিকে এগিয়ে যাচ্ছে।''

---

### প্রশ্নাবলি:
- **(ক)** প্লাস্টিক মানি (Plastic Money) কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** কাগজের মুদ্রার অভ্যন্তরীণ মূল্য বলতে কী বোঝায়? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** ধাতব মুদ্রা, কাগজের নোট এবং আধুনিক প্লাস্টিক কার্ডের সুবিধার তুলনামূলক ছক প্রস্তুত কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** ক্যাশলেস সোসাইটি গঠনে আধুনিক ইলেকট্রনিক ব্যাংকিংয়ের অবদান সারণির মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
ব্যাংক কর্তৃক হিসাবধারীদের নগদ অর্থ বহন না করে ইলেকট্রনিকভাবে লেনদেন নিষ্পত্তির জন্য প্রদত্ত ডেবিট কার্ড, ক্রেডিট কার্ড বা এটিএম কার্ডকে প্লাস্টিক মানি বলে।

#### (খ) অনুধাবনমূলক উত্তর:
যে কাগজ দিয়ে নোট তৈরি করা হয় তার নিজস্ব বাজারমূল্যকে অভ্যন্তরীণ মূল্য বলে। কাগজের নোটের অভ্যন্তরীণ মূল্য প্রায় শূন্য, কিন্তু রাষ্ট্রীয় কর্তৃত্ব ও কেন্দ্রীয় ব্যাংকের আদেশের বলে এর আইনগত বিনিময় মূল্য অনেক বেশি।

#### (গ) প্রয়োগমূলক উত্তর:
মুদ্রার রূপান্তরের তুলনামূলক সারণি:

| বৈশিষ্ট্য | ধাতব মুদ্রা (স্বর্ণ/রৌপ্য) | কাগজের মুদ্রা (নোট) | প্লাস্টিক কার্ড ও ডিজিটাল মানি |
| :--- | :--- | :--- | :--- |
| **বহন সুবিধা** | ভারী ও কষ্টসাধ্য | হালকা ও সহজে পকেটে বহনযোগ্য | অতি ক্ষুদ্র একটি কার্ড বা স্মার্টফোন |
| **নিরাপত্তা** | চুরি ও ডাকাতির চরম ঝুঁকি | ছিনতাই ও জাল নোটের ঝুঁকি থাকে | পিন (PIN) ও ওটিপি সুরক্ষিত, চুরির ভয় নেই |
| **আন্তর্জাতিক ব্যবহার** | সীমানা পেরিয়ে বহন নিষিদ্ধ | মুদ্রা বিনিময় ও ডিক্লারেশন ঝামেলা | কার্ডে বিশ্বের যেকোনো প্রান্তে তাৎক্ষণিক পেমেন্ট |
| **হিসাব সংরক্ষণ** | কোনো স্বয়ংক্রিয় ট্র্যাকিং নেই | ব্যক্তিগত ডায়েরি লিখতে হয় | প্রতিটি খরচের এসএমএস ও ডিজিটাল স্টেটমেন্ট |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
ক্যাশলেস সোসাইটি ও ডিজিটাল ব্যাংকিংয়ের প্রভাব সারণি:

| ক্ষেত্র | নগদভিত্তিক সমাজ (Cash-based) | ডিজিটাল ক্যাশলেস সমাজ (Cashless) |
| :--- | :--- | :--- |
| **জাল নোট ও অপরাধ** | জাল টাকা ও ছিনতাইয়ের উচ্চ ঝুঁকি | শূন্য ক্যাশ লেনদেনে ছিনতাই ও চাঁদাবাজি রোধ |
| **মুদ্রা ছাপানোর খরচ** | প্রতি বছর শত শত কোটি টাকা নোট ছাপাতে ব্যয় | কাগজ ও মুদ্রণ খরচ শতভাগ সাশ্রয় |
| **লেনদেনের গতি** | লাইনে দাঁড়িয়ে নগদ টাকা গোনার ঝামেলা | কিউআর কোড বা কি-বোর্ডের এক ক্লিকে পেমেন্ট |
| **কালো টাকা রোধ** | নগদ লেনদেনের কোনো ব্যাংকিং ট্রেইল থাকে না | প্রতিটি আর্থিক লেনদেনের শতভাগ স্বচ্ছ ডিজিটাল রেকর্ড |

**উপসংহার:** তানজিমের বক্তব্য যথার্থ। নগদ টাকা বহনের ঝুঁকি ও অপচয় দূর করে আধুনিক প্লাস্টিক মানি বাংলাদেশকে একটি আধুনিক, স্বচ্ছ ও স্মার্ট ক্যাশলেস অর্থনীতির দিকে এগিয়ে নিয়ে যাচ্ছে।
', 3);

