    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ৯ম অধ্যায়: ব্যাংকিং ব্যবসায় ও তার ধরন (Banking Business & Types)

---

### ৯.১ ব্যাংকিং ব্যবসায়ের মৌলিক উদ্দেশ্য
১. **মালিক ও শেয়ারহোল্ডারদের দৃষ্টিকোণ থেকে:** মূলধনের নিরাপত্তা, কাঙ্ক্ষিত মুনাফা অর্জন ও সুনামের বৃদ্ধি।
২. **গ্রাহকের দৃষ্টিকোণ থেকে:** অলস অর্থের নিরাপত্তা, সুদ উপার্জন ও সহজে লেনদেন নিষ্পত্তির সুবিধা।
৩. **সরকার ও অর্থনীতির দৃষ্টিকোণ থেকে:** মূলধন গঠন, মুদ্রাবাজার নিয়ন্ত্রণ ও কর্মসংস্থান সৃষ্টি।

---

### ৯.২ ব্যাংকিং ব্যবসায়ের মূল নীতিমালা
- **নিরাপত্তার নীতি:** অর্থ নিরাপদ ঋণগ্রহীতার নিকট বিনিয়োগ করা।
- **তারল্য নীতি:** চাহিবামাত্র গ্রাহকের টাকা ফেরতের নগদ তহবিল রাখা।
- **মুনাফা নীতি:** কম সুদে আমানত এনে বেশি সুদে ঋণ দিয়ে লাভ করা।
- **গোপনীয়তার নীতি:** গ্রাহকের ব্যাংক হিসাবের তথ্য সংরক্ষণ।

---

### ৯.৩ সাংগঠনিক কাঠামোর ভিত্তিতে শ্রেণিবিভাগ
1. **একক ব্যাংক (Unit Banking):** একটিমাত্র ভবনে সীমিত কার্যক্রম, কোনো শাখা থাকে না।
2. **শাখা ব্যাংক (Branch Banking):** প্রধান কার্যালয়ের অধীনে দেশব্যাপী শাখা বিস্তার (যেমন: সোনালী ব্যাংক, ডাচ-বাংলা ব্যাংক)।
3. **চেইন ব্যাংক (Chain Banking):** সমশ্রেণির কয়েকটি ব্যাংক নিজেদের অস্তিত্ব টিকিয়ে রেখে যৌথ ব্যবস্থাপনায় পরিচালিত হয়।
4. **গ্রুপ ব্যাংক (Group Banking):** একটি প্রধান হোল্ডিং কোম্পানির নিয়ন্ত্রণে একাধিক সাবসিডিয়ারি ব্যাংক পরিচালিত হয়।
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (শাখা ব্যাংক বনাম একক ব্যাংক ব্যবস্থা)

### উদ্দীপক:
> জনতা ব্যাংক লিমিটেড বাংলাদেশে প্রায় সহস্রাধিক শাখা নিয়ে পরিচালিত হচ্ছে। প্রতিটি শাখা কেন্দ্রীয় প্রধান কার্যালয়ের অধীনে নিয়ন্ত্রিত হয় এবং যেকোনো নাগরিক সহজেই দেশের এক প্রান্ত থেকে অন্য প্রান্তে তাৎক্ষণিক টাকা পাঠাতে পারেন। অন্যদিকে মার্কিন যুক্তরাষ্ট্রে এমন কিছু ব্যাংক আছে যাদের একটিমাত্র নির্দিষ্ট অফিস ছাড়া অন্য কোনো শাখা নেই।

---

### প্রশ্নাবলি:
- **(ক)** একক ব্যাংক (Unit Bank) কাকে বলে? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ব্যাংকের তারল্য নীতি বলতে কী বোঝায়? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** উদ্দীপকে উল্লিখিত জনতা ব্যাংকের শাখা ব্যাংকিং এবং আমেরিকান একক ব্যাংকের কাঠামোগত পার্থক্যের ছক তৈরি কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** বাংলাদেশের আর্থ-সামাজিক প্রেক্ষাপটে শাখা ব্যাংক ব্যবস্থা বনাম একক ব্যাংকের উপযোগিতা সারণির মাধ্যমে বিশ্লেষণ কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
যে ব্যাংকের কোনো শাখা থাকে না এবং একটিমাত্র কার্যালয়ের মাধ্যমে যাবতীয় ব্যাংকিং কার্যক্রম পরিচালিত হয়, তাকে একক ব্যাংক (Unit Bank) বলে।

#### (খ) অনুধাবনমূলক উত্তর:
গ্রাহক ব্যাংকে জমা রাখা টাকা চাওয়া মাত্র ফেরত দেওয়ার সামর্থ্যকে ব্যাংকের তারল্য নীতি বলে। ব্যাংক যদি সব আমানতের টাকা দীর্ঘমেয়াদী ঋণ হিসেবে দিয়ে দেয় তবে গ্রাহকের আমানত ফেরত দিতে পারবে না; ফলে ব্যাংকের ওপর গ্রাহকের আস্থা নষ্ট হবে। তাই একটি নির্দিষ্ট পরিমাণ নগদ তহবিল সব সময় তারল্য হিসেবে সংরক্ষণ করতে হয়।

#### (গ) প্রয়োগমূলক উত্তর:
শাখা ব্যাংক বনাম একক ব্যাংকের কাঠামোগত পার্থক্য সারণি:

| তুলনার ভিত্তি | শাখা ব্যাংক ব্যবস্থা (জনতা ব্যাংক) | একক ব্যাংক ব্যবস্থা (আমেরিকান মডেল) |
| :--- | :--- | :--- |
| **সাংগঠনিক কাঠামো** | একটি প্রধান কার্যালয়ের অধীনে দেশজুড়ে শত শত শাখা থাকে | একটিমাত্র অফিসের মধ্যেই সমস্ত কার্যক্রম সীমাবদ্ধ |
| **ভৌগোলিক পরিধি** | জাতীয় ও আন্তর্জাতিক পর্যায়ে বিস্তৃত | একটি নির্দিষ্ট শহর বা এলাকায় সীমাবদ্ধ |
| **মূলধনের পরিমাণ** | সুবিশাল মূলধন ও সম্পদ ভিত্তি | তুলনামূলকভাবে ক্ষুদ্র মূলধন |
| **ঝুঁকি বণ্টন** | এক শাখার লোকসান অন্য শাখার লাভ দিয়ে সামাল দেওয়া যায় | কোনো ঝুঁকি বণ্টন সম্ভব নয়; স্থানীয় সংকটে দেউলিয়া হতে পারে |
| **রেমিট্যান্স ও অর্থ স্থানান্তর** | এক শাখা থেকে অন্য শাখায় তাৎক্ষণিক অর্থ স্থানান্তর সম্ভব | অন্য প্রতিষ্ঠানের সাহায্য ছাড়া দূরবর্তী লেনদেন জটিল |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
বাংলাদেশের প্রেক্ষাপটে উভয় ব্যাংকিং ব্যবস্থার উপযোগিতা মূল্যায়ন সারণি:

| মূল্যায়নের মাপকাঠি | শাখা ব্যাংকিংয়ের কার্যকারিতা | একক ব্যাংকিংয়ের সীমাবদ্ধতা |
| :--- | :--- | :--- |
| **গ্রামীণ আর্থিক অন্তর্ভুক্তি** | দুর্গম পাহাড়ি ও চরাঞ্চলেও শাখা খুলে কৃষক ও প্রান্তিক মানুষকে সেবা দেওয়া যায় | গ্রামীণ এলাকায় কার্যক্রম পরিচালনা করা অর্থনৈতিকভাবে অলাভজনক |
| **অর্থনৈতিক স্থায়িত্ব** | মন্দা বা প্রাকৃতিক দুর্যোগেও বড় মূলধনের কারণে ব্যাংক টিকে থাকে | সামান্য ঋণের খেলাপি হলেই ব্যাংক বন্ধের উপক্রম হয় |
| **সরকারি নীতি বাস্তবায়ন** | সামাজিক নিরাপত্তা ভাতা, কৃষি ঋণ দেশব্যাপী একযোগে বণ্টন সম্ভব | জাতীয় পর্যায়ের কোনো সরকারি দায়িত্ব পালন করতে পারে না |

**চূড়ান্ত মূল্যায়ন:** বাংলাদেশের ঘনবসতিপূর্ণ এবং উন্নয়নশীল অর্থনীতির জন্য শাখা ব্যাংক ব্যবস্থার কোনো বিকল্প নেই। একক ব্যাংক ব্যবস্থা বাংলাদেশের তৃণমূল অর্থনৈতিক উন্নয়নে অনুপযোগী।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (চেইন ব্যাংকিং বনাম গ্রুপ ব্যাংকিং ব্যবস্থাপনা)

### উদ্দীপক:
> ইউরোপের তিনটি সমজাতীয় ব্যাংক ক, খ ও গ একীভূত না হয়েও নিজেদের স্বকীয়তা বজায় রেখে যৌথ নীতি প্রণয়নের জন্য একটি অভিন্ন পরিচালনা পর্ষদের অধীনে পরিচালিত হচ্ছে। অন্যদিকে যুক্তরাজ্যে ''আলফা হোল্ডিং কোম্পানি'' দেশের চারটি বাণিজ্যিক ব্যাংকের ৫১% এর বেশি শেয়ার কিনে নিয়ে সেগুলোকে নিজেদের অধীনস্থ বা সাবসিডিয়ারি ব্যাংক হিসেবে কেন্দ্রীয়ভাবে নিয়ন্ত্রণ করছে।

---

### প্রশ্নাবলি:
- **(ক)** হোল্ডিং কোম্পানি (Holding Company) কাকে বলে? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** চেইন ব্যাংকিংয়ের মূল উদ্দেশ্য কী? ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** উদ্দীপকে বর্ণিত প্রথম ক্ষেত্রটি (ক, খ, গ ব্যাংক) এবং দ্বিতীয় ক্ষেত্রটির (আলফা হোল্ডিং) ব্যাংকিং কাঠামোর তুলনামূলক ছক প্রস্তুত কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** গ্রুপ ব্যাংকিং ব্যবস্থার সুবিধা ও সম্ভাব্য ঝুঁকি একটি সুসংগঠিত সারণির মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
যে প্রধান কোম্পানি অন্য কোনো কোম্পানির ন্যূনতম ৫১% বা তার বেশি ভোটাধিকারযুক্ত শেয়ার ক্রয় করে তার পরিচালনা ও নিয়ন্ত্রণের ক্ষমতা লাভ করে, তাকে হোল্ডিং কোম্পানি বলে।

#### (খ) অনুধাবনমূলক উত্তর:
চেইন ব্যাংকিংয়ের মূল উদ্দেশ্য হলো সমশ্রেণির কয়েকটি ব্যাংক নিজেদের স্বাধীন আইনগত সত্ত্বা টিকিয়ে রেখে যৌথ আঁতাত বা সমঝোতার মাধ্যমে পারস্পরিক অসম প্রতিযোগিতা দূর করা এবং যৌথ সুবিধা গ্রহণ করা।

#### (গ) প্রয়োগমূলক উত্তর:
চেইন ব্যাংকিং বনাম গ্রুপ ব্যাংকিংয়ের কাঠামোগত তুলনামূলক সারণি:

| তুলনার মাপকাঠি | চেইন ব্যাংকিং (ক, খ ও গ ব্যাংক) | গ্রুপ ব্যাংকিং (আলফা হোল্ডিং নিয়ন্ত্রিত) |
| :--- | :--- | :--- |
| **নিয়ন্ত্রণ ব্যবস্থা** | কোনো হোল্ডিং কোম্পানি থাকে না; সমঝোতার মাধ্যমে নিয়ন্ত্রিত | একটি মূল হোল্ডিং কোম্পানির প্রত্যক্ষ অধীনে নিয়ন্ত্রিত |
| **মালিকানার ধরন** | অংশীদার ব্যাংকগুলোর পৃথক মালিকানা বজায় থাকে | হোল্ডিং কোম্পানি ৫১% বা তার বেশি শেয়ার ধারণ করে |
| **আইনগত সত্ত্বা** | প্রতিটি ব্যাংক স্বাধীন সত্ত্বা বজায় রাখে | অধীনস্থ ব্যাংকগুলো সাবসিডিয়ারি হিসেবে কাজ করে |
| **সিদ্ধান্ত গ্রহণ** | সর্বসম্মত ঐকমত্যের ভিত্তিতে সিদ্ধান্ত | মূল হোল্ডিং কোম্পানির বোর্ড থেকে কেন্দ্রীয় সিদ্ধান্ত আসে |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
গ্রুপ ব্যাংকিং ব্যবস্থার সুবিধা ও ঝুঁকি মূল্যায়ন সারণি:

| দিক | ইতিবাচক প্রভাব (সুবিধা) | নেতিবাচক প্রভাব (ঝুঁকি) |
| :--- | :--- | :--- |
| **মূলধন শক্তি** | একাধিক ব্যাংকের মূলধন একত্রিত হওয়ায় বৃহৎ শিল্প ঋণে সুবিধা | মূল হোল্ডিং কোম্পানি ক্ষতিগ্রস্ত হলে সব ব্যাংক দেউলিয়া হওয়ার ঝুঁকি |
| **ব্যয় সংকোচন** | সফটওয়্যার, বিজ্ঞাপন ও গবেষণা কেন্দ্রীয়ভাবে হওয়ায় খরচ কমে | শাখা ব্যাংকগুলোর নিজস্ব স্বাধীনতা ও সৃজনশীলতা হ্রাস পায় |
| **বাজার নিয়ন্ত্রণ** | বাজারে শক্তিশালী প্রভাব বিস্তার ও সুনাম বৃদ্ধি | একচেটিয়া আধিপত্য তৈরি করে গ্রাহকদের ওপর অযৌক্তিক চার্জ চাপানোর ভয় |

**উপসংহার:** গ্রুপ ব্যাংকিং আর্থিক শক্তি বৃদ্ধি করে ঠিকই, তবে যথাযথ কেন্দ্রীয় ব্যাংকিং নিয়ন্ত্রণ না থাকলে এটি আর্থিক বাজারে একচেটিয়া কারবারের সৃষ্টি করতে পারে।
', 3);

