    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ১০ম অধ্যায়: বাণিজ্যিক ব্যাংক ও তার পরিচিতি (Commercial Bank)

---

### ১০.১ বাণিজ্যিক ব্যাংকের ধারণা
মুনাফা অর্জনের মূল উদ্দেশ্যে যে আর্থিক প্রতিষ্ঠান জনসাধারণের নিকট থেকে আমানত গ্রহণ করে, ব্যবসায়ীদের ঋণ দেয় এবং বিভিন্ন ব্যাংকিং সেবা প্রদান করে, তাকে বাণিজ্যিক ব্যাংক বলে।

---

### ১০.২ মৌলিক কার্যাবলি
১. **আমানত গ্রহণ:** চলতি, সঞ্চয়ী ও স্থায়ী আমানত হিসেবে তহবিল সংগ্রহ।
২. **ঋণ প্রদান:** শিল্প, কৃষি ও ব্যবসায়ীদের জামানতের বিপরীতে স্বল্প ও মধ্যমেয়াদী ঋণ দান।
৩. **ঋণ আমানত সৃষ্টি (Credit Creation):** ঋণ চেকের মাধ্যমে প্রদান করে নতুন আমানত সৃষ্টি।
৪. **বিনিময় বিল বাট্টাকরণ:** মেয়াদ উত্তীর্ণের পূর্বেই ব্যবসায়ী বিল বাট্টা করে তাৎক্ষণিক অর্থায়ন করে।
৫. **বৈদেশিক বাণিজ্যে সহায়তা:** ঋণপত্র (Letter of Credit - LC) প্রদান ও মুদ্রা বিনিময়।

---

### ১০.৩ আয়ের উৎস ও ব্যয়ের খাত
- **প্রধান আয়:** ঋণগ্রহীতার নিকট থেকে প্রাপ্ত সুদ এবং আমানতকারীকে প্রদত্ত সুদের মধ্যকার মার্জিন বা স্প্রেড (Spread)। অন্যান্য আয়ের মধ্যে কমিশন, বাট্টা, ব্রোকারেজ ও লকার ভাড়া অন্তর্ভুক্ত।
- **প্রধান ব্যয়:** আমানতের সুদ, কর্মকর্তা-কর্মচারীদের বেতন, অফিস ভাড়া ও তথ্যপ্রযুক্তি ব্যবস্থাপনা ব্যয়।
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (ঋণ আমানত সৃষ্টি ও সুদের মার্জিন স্প্রেড)

### উদ্দীপক:
> প্রাইম কমার্শিয়াল ব্যাংক জনসাধারণের নিকট থেকে গড়ে ৫% সুদে আমানত গ্রহণ করে। উক্ত সংগৃহীত তহবিলের ২০% নগদ তারল্য হিসেবে সংরক্ষণ করে অবশিষ্ট অংশ ৯% সুদে বিভিন্ন শিল্পোদ্যোক্তা ও ব্যবসায়ীদের ঋণ প্রদান করে। ঋণ প্রদানের সময় ব্যাংক নগদ টাকা না দিয়ে ঋণগ্রহীতার নামে হিসাব খুলে চেকের মাধ্যমে ব্যবহারের সুযোগ দেয়। এছাড়া ব্যাংকটি বৈদেশিক বাণিজ্যের জন্য এলসি (LC) খোলা, বিনিময় বিল বাট্টাকরণ এবং বিভিন্ন সেবার বিনিময়ে কমিশন ও ফি অর্জন করে বিপুল মুনাফা লাভ করে।

---

### প্রশ্নাবলি:
- **(ক)** বাণিজ্যিক ব্যাংকের প্রধান উদ্দেশ্য কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** বাণিজ্যিক ব্যাংকের সুদের ব্যবধান বা স্প্রেড (Spread) বলতে কী বোঝায়? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** উদ্দীপকে বাণিজ্যিক ব্যাংকের ঋণ আমানত সৃষ্টির (Credit Creation) প্রক্রিয়াটি ধাপভিত্তিক ছকের সাহায্যে প্রদর্শন কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** বাণিজ্যিক ব্যাংকের প্রধান আয়ের উৎস ও ব্যয়ের খাতসমূহ একটি কাঠামোগত সারণির মাধ্যমে উপস্থাপন করে এর অর্থনৈতিক গুরুত্ব মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
বাণিজ্যিক ব্যাংকের প্রধান ও মূল চালিকাশক্তি উদ্দেশ্য হলো মুনাফা অর্জন (Profit Maximization)।

#### (খ) অনুধাবনমূলক উত্তর:
বাণিজ্যিক ব্যাংক আমানতকারীকে যে হারে সুদ প্রদান করে এবং ঋণগ্রহীতার নিকট থেকে যে উচ্চ হারে সুদ আদায় করে, এই দুই সুদের হারের পার্থক্যকে ''সুদের ব্যবধান'' বা স্প্রেড (Spread) বলে। এটিই বাণিজ্যিক ব্যাংকের পরিচালন মুনাফার প্রধান উৎস।

#### (গ) প্রয়োগমূলক উত্তর:
বাণিজ্যিক ব্যাংকের ঋণ আমানত সৃষ্টি (Credit Creation) প্রক্রিয়ার ধাপভিত্তিক সারণি:
(ধরা যাক, প্রাথমিক আমানত ১,০০,০০০ টাকা এবং নগদ জমা রিজার্ভ অনুপাত ২০%)

| পর্যায় | নতুন আমানত (টাকা) | বাধ্যতামূলক রিজার্ভ ২০% (টাকা) | নতুন ঋণ মঞ্জুর / সৃষ্ট আমানত (টাকা) |
| :---: | :---: | :---: | :---: |
| **১ম ধাপ** | ১,০০,০০০ | ২০,০০০ | ৮০,০০০ (ঋণগ্রহীতার একাউন্টে জমা) |
| **২য় ধাপ** | ৮০,০০০ | ১৬,০০০ | ৬৪,০০০ |
| **৩য় ধাপ** | ৬৪,০০০ | ১২,৮০০ | ৫১,২০০ |
| **পরবর্তী ধাপসমূহ...** | ... | ... | ... |
| **চূড়ান্ত ঋণ বিস্তার** | **মোট আমানত = ৫,০০,০০০** | **১,০০,০০০** | **মোট ঋণ সৃষ্টি = ৪,০০,০০০ টাকা** |

$$\text{মোট সৃষ্ট আমানত} = \frac{\text{প্রাথমিক আমানত}}{\text{নগদ জমার অনুপাত}} = \frac{১,০০,০০০}{০.২০} = ৫,০০,০০০ \text{ টাকা}$$

**ব্যাখ্যা:** ব্যাংক ঋণগ্রহীতাকে সরাসরি নগদ না দিয়ে তার নামে হিসাব খুলে ঋণ জমা করে। এভাবে মূল এক লক্ষ টাকা থেকে ক্রমান্বয়ে চার লক্ষ টাকার নতুন ঋণ আমানত সৃষ্টি হয়।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
বাণিজ্যিক ব্যাংকের আয়ের উৎস ও ব্যয়ের খাতের তুলনামূলক সারণি:

| প্রধান আয়ের উৎসসমূহ (Incomes) | প্রধান ব্যয়ের খাতসমূহ (Expenses) |
| :--- | :--- |
| ১. ঋণের ওপর আদায়কৃত উচ্চ সুদ (৯%) | ১. আমানতকারীদের প্রদত্ত সুদ (৫%) |
| ২. বিনিময় বিল বাট্টাকরণ কমিশন | ২. কর্মকর্তা-কর্মচারীদের বেতন ও ভাতাদি |
| ৩. বৈদেশিক বাণিজ্য ঋণপত্র (LC) ফি ও কমিশন | ৩. শাখা অফিস ও বুথের ভাড়া ও বিদ্যুৎ বিল |
| ৪. অর্থ স্থানান্তর ফি (ডিডি, টিটি, পে-অর্ডার) | ৪. তথ্যপ্রযুক্তি, সফটওয়্যার ও এটিএম নেটওয়ার্ক রক্ষণাবেক্ষণ |
| ৫. লকার ভাড়া ও এটিএম বার্ষিক সার্ভিস চার্জ | ৫. আমানত বীমা প্রিমিয়াম ও সরকারি কর |

**অর্থনৈতিক গুরুত্ব:** বাণিজ্যিক ব্যাংক সমাজের ক্ষুদ্র অলস সঞ্চয়কে একত্রিত করে বিশাল মূলধন তৈরি করে শিল্পায়নকে গতিশীল রাখে এবং বৈদেশিক বাণিজ্যে গ্যারান্টি প্রদান করে আমদানি-রপ্তানি বাণিজ্য সচল রাখে।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (বৈদেশিক বাণিজ্য ঋণপত্র - LC ও বিনিময় বিল বাট্টাকরণ)

### উদ্দীপক:
> রপ্তানিমুখী পোশাক কারখানা ''এপেক্স ফ্যাশনস'' চীন থেকে ৫০ লক্ষ টাকার আধুনিক সুতা ও রিবন আমদানি করতে চায়। কিন্তু চীনা সরবরাহকারী এপেক্স ফ্যাশনসকে ব্যক্তিগতভাবে চেনে না বলে অগ্রিম অর্থ পরিশোধ ছাড়া কাঁচামাল পাঠাতে অস্বীকৃতি জানায়। এপেক্স ফ্যাশনস তাদের ব্যাংকার ইস্টার্ন ব্যাংকে গিয়ে একটি প্রত্যয়পত্র (Letter of Credit - LC) খোলে। অন্যদিকে তৈরি পোশাক আমেরিকায় রপ্তানি করে প্রাপ্ত ৯০ দিন মেয়াদী একটি বিনিময় বিল তারা তাৎক্ষণিক অর্থের প্রয়োজনে ব্যাংকে বাট্টা করে নগদ তুলে নেয়।

---

### প্রশ্নাবলি:
- **(ক)** ঋণপত্র বা এলসি (Letter of Credit)-এর প্রধান পক্ষ কয়টি? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** বিনিময় বিল বাট্টাকরণ বলতে কী বোঝায়? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** আন্তর্জাতিক বাণিজ্যে এলসি (LC) খোলার ফলে কীভাবে ক্রেতা ও বিক্রেতার মধ্যকার আস্থার সংকট দূর হয়? ছকের সাহায্যে ব্যাখ্যা কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** বিনিময় বিল বাট্টাকরণের মাধ্যমে ব্যাংক কীভাবে মুনাফা অর্জন করে এবং ব্যবসায়ী কীভাবে উপকৃত হন? সারণির মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
আন্তর্জাতিক বাণিজ্যে প্রত্যয়পত্র বা এলসির প্রধান পক্ষ হলো ৪টি: আমদানিকারক, আমদানিকারকের ব্যাংক (ইস্যুকারী ব্যাংক), রপ্তানিকারক এবং রপ্তানিকারকের ব্যাংক (পরামর্শক ব্যাংক)।

#### (খ) অনুধাবনমূলক উত্তর:
কোনো ব্যবসায়ী ভবিষ্যৎ মেয়াদের বিনিময় বিল নির্দিষ্ট মেয়াদপূর্তির পূর্বেই তার বাণিজ্যিক ব্যাংকে উপস্থাপন করে ব্যাংকের বাট্টা বা কমিশন চার্জ বাদ দিয়ে অবশিষ্ট নগদ টাকা তাৎক্ষণিক সংগ্রহ করার প্রক্রিয়াকে বিনিময় বিল বাট্টাকরণ বলে।

#### (গ) প্রয়োগমূলক উত্তর:
এলসি (Letter of Credit) প্রক্রিয়ায় আস্থার সংকট দূরীকরণ সারণি:

| সংশ্লিষ্ট পক্ষ | সাধারণ বাণিজ্যের ভয় / ঝুঁকি | এলসি (LC)-র মাধ্যমে ব্যাংকের প্রদত্ত সুরক্ষা |
| :--- | :--- | :--- |
| **আমদানিকারক (এপেক্স ফ্যাশনস)** | টাকা অগ্রিম পাঠালে সরবরাহকারী সঠিক মাল নাও পাঠাতে পারে | জাহাজীকরণ ও সঠিক দলিল ব্যাংকে জমা না দিলে ব্যাংক টাকা ছাড়বে না |
| **চীনা রপ্তানিকারক** | মাল পাঠালে বিদেশি ক্রেতা হয়তো পরে মূল্য পরিশোধ করবে না | বিদেশি ব্যাংক নিজে মূল্য পরিশোধের শতভাগ লিখিত গ্যারান্টি দেয় |
| **বাণিজ্যিক ব্যাংক** | কমিশন ও বৈদেশিক মুদ্রা ফি আয় করে | আন্তর্জাতিক আর্থিক লেনদেনে মধ্যস্থতা করে আস্থা বৃদ্ধি করে |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
বিনিময় বিল বাট্টাকরণে ব্যাংক বনাম ব্যবসায়ীর পারস্পরিক সুবিধা সারণি:

| নির্দেশক | ব্যাংকের সুবিধা | ব্যবসায়ীর সুবিধা (এপেক্স ফ্যাশনস) |
| :--- | :--- | :--- |
| **মুনাফা ও তারল্য** | ৯০ দিনের জন্য নির্দিষ্ট অঙ্কের বাট্টা/কমিশন কেটে নগদ মুনাফা লাভ | ৯০ দিন অপেক্ষা না করে আজই নগদ টাকা দিয়ে কাঁচামাল ও মজুরি পরিশোধ |
| **ঝুঁকির ধরন** | মেয়াদ শেষে আমদানিকারকের ব্যাংক থেকে বিলের পূর্ণ মূল্য আদায় | চলতি মূলধনের কোনো অচলাবস্থা হয় না; পরিচালন চক্র সচল থাকে |
| **অর্থনৈতিক প্রভাব** | নিরাপদ স্বল্পমেয়াদী বিনিয়োগ নিশ্চিত হয় | সময়মতো অর্ডার তৈরি করে রপ্তানি প্রবৃদ্ধি ধরে রাখা যায় |

**উপসংহার:** বাণিজ্যিক ব্যাংকের এলসি ও বিল বাট্টাকরণ সেবা না থাকলে আন্তর্জাতিক বাণিজ্যের চাকা স্থবির হয়ে পড়ত।
', 3);

