    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ১১শ অধ্যায়: ব্যাংকের আমানত (Bank Deposit)

---

### ১১.১ ব্যাংক আমানতের প্রকারভেদ
১. **চলতি হিসাব (Current Account):** ব্যবসায়ীদের জন্য উপযোগী। দিনে যতবার খুশি টাকা জমা ও উত্তোলন করা যায়। এতে কোনো সুদ দেওয়া হয় না।
২. **সঞ্চয়ী হিসাব (Savings Account):** সাধারণ চাকরিজীবী ও মধ্যবিত্তদের সঞ্চয়ের জন্য। সপ্তাহে বা মাসে নির্দিষ্ট সংখ্যক বার টাকা তোলা যায় এবং ব্যাংক নির্দিষ্ট হারে সুদ প্রদান করে।
৩. **স্থায়ী হিসাব (Fixed Deposit - FDR):** একটি নির্দিষ্ট মেয়াদের জন্য এককালীন টাকা জমা রাখা হয়। এতে সর্বোচ্চ হারে সুদ পাওয়া যায়।

---

### ১১.২ চেকের প্রকারভেদ
- **বাহক চেক (Bearer Cheque):** যে কেউ ব্যাংকে উপস্থাপন করে কাউন্টার থেকে তাৎক্ষণিক নগদ টাকা গ্রহণ করতে পারে।
- **হুকুম চেক (Order Cheque):** চেকে নির্দিষ্ট প্রাপকের নাম উল্লেখ থাকে; পরিচয় যাচাই ছাড়া অন্য কাউকে টাকা দেওয়া হয় না।
- **রেখাঙ্কিত চেক (Crossed Cheque):** চেকের কোণায় দুটি সমান্তরাল দাগ কাটা থাকে। টাকা নগদে না দিয়ে প্রাপকের ব্যাংক হিসাবে জমা করতে হয়।

---

### ১১.৩ আধুনিক ইলেকট্রনিক ব্যাংকিং
- **ATM (Automated Teller Machine):** ২৪ ঘণ্টা যেকোনো স্থান থেকে নগদ টাকা উত্তোলন ও জমা দেওয়ার স্বয়ংক্রিয় বুথ।
- **ডেবিট কার্ড:** গ্রাহকের নিজের ব্যাংক হিসাবে থাকা টাকা থেকে সরাসরি কেনাকাটা ও ক্যাশ উত্তোলনের কার্ড।
- **ক্রেডিট কার্ড:** ব্যাংকের অনুমোদনকৃত নির্দিষ্ট ঋণসীমা পর্যন্ত বাকি বা ধারে কেনাকাটার কার্ড।
- **মোবাইল ও ইন্টারনেট ব্যাংকিং:** মোবাইল অ্যাপ বা ওয়েবসাইটের মাধ্যমে ঘরে বসে অর্থ স্থানান্তর ও বিল পরিশোধ।
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (চলতি, সঞ্চয়ী হিসাব ও রেখাঙ্কিত চেকের নিরাপত্তা)

### উদ্দীপক:
> জনাব আসাদ একজন পাইকারি ব্যবসায়ী, যাকে প্রতিদিন একাধিকবার ব্যাংকে বিপুল পরিমাণ টাকা জমা ও উত্তোলন করতে হয়। অপরদিকে তার স্ত্রী মিসেস নাজনীন একজন স্কুল শিক্ষিকা, যিনি প্রতি মাসের বেতনের একটি অংশ সঞ্চয় করতে চান এবং মাসে সর্বোচ্চ দু-একবার টাকা তোলেন। সম্প্রতি জনাব আসাদ তার পাওনাদারের নিকট থেকে ৫০,০০০ টাকার একটি রেখাঙ্কিত চেক পান, যা তিনি ব্যাংক কাউন্টারে সরাসরি নগদে রূপান্তর করতে পারেননি।

---

### প্রশ্নাবলি:
- **(ক)** রেখাঙ্কিত চেক (Crossed Cheque) কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** স্থায়ী আমানত (FDR) বলতে কী বোঝায়? ব্যাখ্যা কর। *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** জনাব আসাদ ও মিসেস নাজনীনের জন্য উপযুক্ত ব্যাংক হিসাবের বৈশিষ্ট্য ও পার্থক্যের একটি তুলনামূলক ছক তৈরি কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** জনাব আসাদের রেখাঙ্কিত চেক কাউন্টার থেকে ক্যাশ না হওয়ার কারণ এবং বাহক চেক বনাম রেখাঙ্কিত চেকের নিরাপত্তা ছকের মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
যে চেকের বামদিকের উপরের কোণায় দুটি সমান্তরাল আড়াআড়ি দাগ বা রেখা টেনে দেওয়া হয় এবং যার অর্থ কাউন্টারে নগদে না দিয়ে নির্দিষ্ট ব্যাংক হিসাবে জমা করতে হয়, তাকে রেখাঙ্কিত চেক বলে।

#### (খ) অনুধাবনমূলক উত্তর:
একটি নির্দিষ্ট মেয়াদের (যেমন: ৩ মাস, ৬ মাস, ১ বছর বা ৫ বছর) জন্য যে আমানত ব্যাংকে জমা রাখা হয় এবং মেয়াদের পূর্বে সাধারণ নিয়মে টাকা তোলা যায় না, তাকে স্থায়ী আমানত বা ফিক্সড ডিপোজিট (FDR) বলে। এতে সুদের হার সবচেয়ে বেশি থাকে।

#### (গ) প্রয়োগমূলক উত্তর:
চলতি হিসাব (জনাব আসাদ) বনাম সঞ্চয়ী হিসাব (মিসেস নাজনীন)-এর তুলনামূলক সারণি:

| তুলনার ভিত্তি | চলতি হিসাব (Current Account) | সঞ্চয়ী হিসাব (Savings Account) |
| :--- | :--- | :--- |
| **উপযুক্ত গ্রাহক** | ব্যবসায়ী ও বাণিজ্যিক প্রতিষ্ঠান (জনাব আসাদ) | চাকরিজীবী, শিক্ষক ও মধ্যবিত্ত পরিবার (মিসেস নাজনীন) |
| **টাকা তোলার নিয়ম** | কার্যদিবসে দিনে যতবার খুশি টাকা তোলা যায় | সপ্তাহে বা মাসে নির্দিষ্ট সংখ্যক বার (যেমন সপ্তাহে ২ বার) |
| **সুদ প্রাপ্তি** | কোনো প্রকার সুদ প্রদান করা হয় না | জমার ওপর ব্যাংক নির্দিষ্ট হারে সুদ প্রদান করে |
| **ওভারড্রাফট সুবিধা** | জমাতীত উত্তোলন (O/D) সুবিধা পাওয়া যায় | এই সুবিধা সাধারণ নিয়মে প্রযোজ্য নয় |
| **মূল উদ্দেশ্য** | সার্বক্ষণিক সহজ বাণিজ্যিক লেনদেন নিষ্পত্তি | ভবিষ্যত সুরক্ষার জন্য ক্ষুদ্র সঞ্চয় বৃদ্ধি |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
চেকের প্রকারভেদ ও নিরাপত্তা বিশ্লেষণ সারণি:

| চেকের ধরন | নগদ উত্তোলনের নিয়ম | নিরাপত্তার মাত্রা | চুরি বা হারিয়ে যাওয়ার ঝুঁকি |
| :--- | :--- | :---: | :--- |
| **বাহক চেক (Bearer Cheque)** | যে কেউ ব্যাংক কাউন্টারে উপস্থাপন করে তাৎক্ষণিক নগদ টাকা গ্রহণ করতে পারে | সর্বনিম্ন | চরম ঝুঁকিপূর্ণ; যে কেউ ক্যাশ হাতিয়ে নিতে পারে |
| **হুকুম চেক (Order Cheque)** | চেকে নির্দিষ্ট প্রাপকের নাম যাচাই করে অর্থ প্রদান করা হয় | মাঝারি | পরিচয় জালিয়াতি করে টাকা তোলার ঝুঁকি থাকে |
| **রেখাঙ্কিত চেক (Crossed Cheque)** | কাউন্টারে কখনোই নগদ দেওয়া হয় না; প্রাপকের ব্যাংক একাউন্টে জমা হয় | **সর্বোচ্চ (১০০% নিরাপদ)** | হারিয়ে গেলেও অপরিচিত কেউ নগদ তুলতে পারে না; ব্যাংকিং ট্রেইল থাকে |

**উপসংহার:** রেখাঙ্কিত চেকে অর্থ কেবল একাউন্ট পেয়ী হওয়ায় জনাব আসাদ কাউন্টার থেকে নগদ পাননি। এই রেখাঙ্কন পদ্ধতি ব্যবসায়িক জালিয়াতি রোধে এক অনন্য আর্থিক সুরক্ষা কবচ।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (ডেবিট কার্ড, ক্রেডিট কার্ড ও এটিএম সাইবার নিরাপত্তা)

### উদ্দীপক:
> জনাব মুশফিক ঈদের শপিং করতে গিয়ে একটি ডিপার্টমেন্টাল স্টোরে নিজের ডেবিট কার্ড ব্যবহার করে বিল পরিশোধ করেন। একই দোকানে তার বন্ধু রায়হান সাহেব নিজের ব্যাংক একাউন্টে পর্যাপ্ত টাকা না থাকা সত্ত্বেও ব্যাংকের দেওয়া ক্রেডিট কার্ড ব্যবহার করে ৫০,০০০ টাকার ইলেকট্রনিক্স পণ্য ক্রয় করেন। বাড়ি ফেরার পথে রায়হানের মোবাইলে অচেনা নম্বর থেকে কল করে কার্ডের ওটিপি (OTP) ও পিন নম্বর চাওয়া হয়। রায়হান সতর্ক থাকায় কোনো তথ্য দেননি।

---

### প্রশ্নাবলি:
- **(ক)** প্লাস্টিক কার্ডের পিন (PIN)-এর পূর্ণরূপ কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ডেবিট কার্ড ও ক্রেডিট কার্ডের মূল পার্থক্য কী? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** ডেবিট কার্ড বনাম ক্রেডিট কার্ডের সুযোগ-সুবিধা ও দায়বদ্ধতার একটি তুলনামূলক ছক প্রস্তুত কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** এটিএম ও অনলাইন কার্ডের সাইবার নিরাপত্তা রক্ষায় গ্রাহক এবং ব্যাংকের পালনীয় পদক্ষেপের একটি কাঠামোগত সারণি তৈরি করে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
PIN-এর পূর্ণরূপ হলো Personal Identification Number (ব্যক্তিগত শনাক্তকরণ নম্বর)।

#### (খ) অনুধাবনমূলক উত্তর:
ডেবিট কার্ডে গ্রাহক শুধুমাত্র তার ব্যাংক হিসাবে পূর্বে জমাকৃত নগদ টাকার সীমা পর্যন্ত খরচ করতে পারেন; অপরদিকে ক্রেডিট কার্ডে ব্যাংক গ্রাহকের আয় ও সুনামের ওপর ভিত্তি করে একটি নির্দিষ্ট ঋণসীমা (Credit Limit) অনুমোদন করে, যার ফলে হিসাবে টাকা না থাকলেও ধারে কেনাকাটা করা যায়।

#### (গ) প্রয়োগমূলক উত্তর:
ডেবিট কার্ড বনাম ক্রেডিট কার্ডের তুলনামূলক সারণি:

| তুলনার মাপকাঠি | ডেবিট কার্ড (জনাব মুশফিক) | ক্রেডিট কার্ড (জনাব রায়হান) |
| :--- | :--- | :--- |
| **তহবিলের উৎস** | গ্রাহকের নিজস্ব জমাকৃত ব্যাংক আমানত | ব্যাংক কর্তৃক প্রদত্ত পূর্বানুমোদিত ঋণ সুবিধা |
| **ব্যাংক একাউন্ট** | ব্যাংক একাউন্ট থাকা বাধ্যতামূলক | ব্যাংক একাউন্ট না থাকলেও ইস্যু করা সম্ভব |
| **সুদের বাধ্যবাধকতা** | কোনো সুদের চার্জ নেই | নির্দিষ্ট সময় (যেমন ৪৫ দিন) পর বাকি টাকার ওপর উচ্চ সুদ ধার্য হয় |
| **ঋণের বোঝা** | ঋণগ্রস্ত হওয়ার কোনো ভয় নেই | অনিয়ন্ত্রিত ব্যবহারে ঋণের ফাঁদে পড়ার ঝুঁকি থাকে |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
কার্ড ও অনলাইন ব্যাংকিংয়ের সাইবার সুরক্ষা সারণি:

| পক্ষ | পালনীয় দায়িত্ব ও নিরাপত্তামূলক পদক্ষেপ | লঙ্ঘনের ঝুঁকি |
| :--- | :--- | :--- |
| **গ্রাহকের দায়িত্ব** | ১. কার্ডের ৪ ডিজিটের পিন (PIN) কাউকে না বলা<br>২. ফোনে ওটিপি (OTP) বা সিভিভি (CVV) কোড শেয়ার না করা<br>৩. বুথে টাকা তোলার সময় কি-প্যাড হাত দিয়ে আড়াল করা | কার্ড ক্লোনিং ও মুহূর্তেই একাউন্ট খালি হওয়া |
| **ব্যাংকের দায়িত্ব** | ১. তাৎক্ষণিক এসএমএস অ্যালার্ট নোটিফিকেশন পাঠানো<br>২. ইএমভি (EMV) চিপযুক্ত আধুনিক কার্ড সরবরাহ করা<br>৩. সন্দেহজনক লেনদেন শনাক্ত করে কার্ড স্বয়ংক্রিয় ব্লক করা | ব্যাংকের প্রতি গ্রাহকের আস্থা নষ্ট ও ক্ষতিপূরণ মামলা |

**উপসংহার:** রায়হান কোনো তথ্য না দিয়ে দায়িত্বশীলতার পরিচয় দিয়েছেন। আধুনিক কার্ড ব্যবস্থা জীবনকে সহজ করেছে ঠিকই, তবে সচেতনতাই হলো সাইবার নিরাপত্তার প্রধান চাবিকাঠি।
', 3);

