    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ১২শ অধ্যায়: ব্যাংক ও গ্রাহক (Bank & Customer)

---

### ১২.১ সম্পর্কের প্রকৃতি
- **দেনাদার ও পাওনাদার:** গ্রাহক যখন টাকা জমা রাখে তখন গ্রাহক পাওনাদার এবং ব্যাংক দেনাদার। আবার ব্যাংক যখন ঋণ দেয় তখন ব্যাংক পাওনাদার ও গ্রাহক দেনাদার।
- **ট্রাস্টি ও বেনিফিশিয়ারি:** গ্রাহকের মূল্যবান সম্পদ ও দলিল লকারে নিরাপদ সংরক্ষণের ক্ষেত্রে ব্যাংক ট্রাস্টি হিসেবে দায়িত্ব পালন করে।
- **প্রতিনিধি ও মক্কেল:** গ্রাহকের পক্ষে চেক সংগ্রহ, বিল পরিশোধ বা শেয়ারের লভ্যাংশ আদায়ে ব্যাংক প্রতিনিধি (Agent) হিসেবে কাজ করে।

---

### ১২.২ ব্যাংকের প্রধান দায়িত্বসমূহ
১. গ্রাহকের চেকে চাহিবামাত্র টাকা পরিশোধ করা।
২. হিসাবের যাবতীয় তথ্যের গোপনীয়তা রক্ষা করা।
৩. সঠিক ও স্বচ্ছ হিসাব বিবরণী সংরক্ষণ করা।

---

### ১২.৩ হিসাব বন্ধ হওয়ার কারণসমূহ
- গ্রাহক নিজে স্বেচ্ছায় লিখিত আবেদন জানালে।
- গ্রাহকের মৃত্যু হলে অথবা আদালত কর্তৃক মস্তিষ্কবিকৃত বা দেউলিয়া ঘোষিত হলে।
- আদালত কর্তৃক গার্নিশি অর্ডার (Garnishee Order) জারি হলে।
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (ভুলবশত চেক ডিজঅনার ও ক্ষতিপূরণ দাবি)

### উদ্দীপক:
> জনাব শওকত আলীর ব্যাংক হিসাবে ৫০,০০০ টাকা জমা থাকা সত্ত্বেও ব্যাংক ভুলবশত তার ইস্যুকৃত ২০,০০০ টাকার একটি বৈধ চেক পর্যাপ্ত তহবিল নেই মর্মে প্রত্যাখ্যান বা ডিজঅনার (Dis-honor) করে। এতে বাজারে প্রাপকের নিকট জনাব শওকত আলীর ব্যবসায়িক সম্মানহানি ঘটে এবং তিনি ব্যাংকের বিরুদ্ধে মামলা দায়েরের প্রস্তুতি নেন। পরবর্তীতে তদন্তে প্রমাণিত হয় ব্যাংকের কম্পিউটার অপারেটরের অসাবধানতাবশত এই ত্রুটি ঘটেছিল।

---

### প্রশ্নাবলি:
- **(ক)** ব্যাংক ও গ্রাহকের মূল সম্পর্কের ধরনটি কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** গার্নিশি অর্ডার (Garnishee Order) বলতে কী বোঝায়? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** ব্যাংক ও গ্রাহকের মধ্যকার পারস্পরিক সম্পর্ক ও দায়িত্বের একটি তুলনামূলক ছক প্রস্তুত কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** ব্যাংকের গাফিলতিতে চেক ডিজঅনার হওয়ার প্রেক্ষিতে জনাব শওকত আলীর আইনগত অধিকার ও ক্ষতিপূরণ দাবি সারণির মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
আইনগত দিক থেকে ব্যাংক ও গ্রাহকের মৌলিক সম্পর্ক হলো দেনাদার ও পাওনাদারের (Debtor and Creditor) সম্পর্ক।

#### (খ) অনুধাবনমূলক উত্তর:
আদালত কর্তৃক কোনো গ্রাহকের ব্যাংক হিসাবের লেনদেন স্থগিত বা জব্দ করার জন্য ব্যাংকের ওপর যে নিষেধাজ্ঞা জারি করা হয়, তাকে গার্নিশি অর্ডার বলে। এই আদেশ জারি হলে ব্যাংক গ্রাহকের টাকা ফেরত দিতে পারে না।

#### (গ) প্রয়োগমূলক উত্তর:
ব্যাংক ও গ্রাহকের সম্পর্কের বিভিন্ন মাত্রা ও পারস্পরিক বাধ্যবাধকতা সারণি:

| সম্পর্কের ধরন | ব্যাংকের ভূমিকা ও দায়িত্ব | গ্রাহকের ভূমিকা ও দায়িত্ব |
| :--- | :--- | :--- |
| **দেনাদার-পাওনাদার** | গ্রাহক টাকা চাইলে তাৎক্ষণিক ফেরত দিতে বাধ্য | সততার সাথে টাকা জমা ও ঋণের কিস্তি শোধ করা |
| **ট্রাস্টি-সুবিধাভোগী** | লকারে রাখা স্বর্ণালঙ্কার বা দলিলের সুরক্ষা নিশ্চিত করা | লকার ভাড়া পরিশোধ ও নিষিদ্ধ বস্তু না রাখা |
| **প্রতিনিধি-মক্কেল** | গ্রাহকের পক্ষে চেক সংগ্রহ, লভ্যাংশ আদায় ও বিল পরিশোধ | নির্দিষ্ট সেবা ফি প্রদান ও প্রয়োজনীয় অনুমোদন দেওয়া |
| **গোপনীয়তা রক্ষা** | আদালতের নির্দেশ ছাড়া হিসাবের তথ্য প্রকাশ না করা | চেকবই সতর্কতার সাথে নিজের জিম্মায় রাখা |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
চেক ডিজঅনারের আইনি প্রভাব ও ক্ষতিপূরণ মূল্যায়ন সারণি:

| বিবেচ্য বিষয় | ব্যাংকের চুক্তিভঙ্গ ও গাফিলতি | জনাব শওকতের আইনগত অধিকার |
| :--- | :--- | :--- |
| **চুক্তির শর্ত** | হিসাবে পর্যাপ্ত টাকা (৫০,০০০ > ২০,০০০) থাকা সত্ত্বেও চেক ফেরত দেওয়া | গ্রাহকের অধিকার লঙ্ঘন হওয়ায় দেওয়ানি আদালতে প্রতিকার চাওয়া |
| **বাণিজ্যিক ক্ষতি** | বাজারে ব্যবসায়ীর ক্রেডিট রেটিং ও সুনামের অপূরণীয় ক্ষতি | সুনামহানির ক্ষতিপূরণ দাবি করার আইনগত অধিকার |
| **ব্যাংকিং দায়বদ্ধতা** | ব্যাংকিং আইন ও বাংলাদেশ ব্যাংকের গাইডলাইনের ব্যত্যয় | আদালতের মাধ্যমে ব্যাংককে উপযুক্ত ক্ষতিপূরণ দিতে বাধ্য করা |

**চূড়ান্ত রায়:** জনাব শওকত আলীর ক্ষতিপূরণ দাবি শতভাগ যৌক্তিক। ব্যাংকের ভুলের কারণে গ্রাহকের বাণিজ্যিক সম্মান বিনষ্ট হলে ব্যাংক ক্ষতিপূরণ দিতে আইনত বাধ্য।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (ব্যাংক লকার নিরাপত্তা, ট্রাস্টি সম্পর্ক ও হিসাব সমাপ্তি)

### উদ্দীপক:
> ব্যবসায়ী জনাব ইকবাল আহমেদ ব্যাংকের লকার ভাড়া নিয়ে সেখানে পারিবারিক দলিলপত্র ও ৫০ ভরি স্বর্ণালঙ্কার সংরক্ষণ করেন। কিন্তু সম্প্রতি আদালত থেকে তার বিরুদ্ধে অর্থ আত্মসাতের মামলায় হিসাবের ওপর গার্নিশি অর্ডার (Garnishee Order) জারি হয়। একই সাথে ব্যাংক জানতে পারে যে ইকবাল সাহেব আদালত কর্তৃক দেউলিয়া ঘোষিত হয়েছেন। এমতাবস্থায় ব্যাংক তার হিসাবের যাবতীয় লেনদেন তাৎক্ষণিক বন্ধ করে দেয় এবং তার পরিবারের চেক প্রত্যাখ্যান করে।

---

### প্রশ্নাবলি:
- **(ক)** ব্যাংক লকারে সংরক্ষিত সম্পদের ক্ষেত্রে ব্যাংক ও গ্রাহকের সম্পর্ক কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** ব্যাংক কোন কোন পরিস্থিতিতে গ্রাহকের হিসাব বন্ধ করতে বাধ্য থাকে? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** উদ্দীপকে ইকবাল সাহেবের ব্যাংক হিসাব বন্ধ করার পেছনে যে আইনগত কারণগুলো ঘটেছে তার একটি সারণি তৈরি কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** ব্যাংক কর্তৃক ইকবাল সাহেবের পরিবারের চেক প্রত্যাখ্যান ও লেনদেন বন্ধের পদক্ষেপের যৌক্তিকতা ছকভিত্তিক বিশ্লেষণ কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
লকারে সংরক্ষিত সম্পদের ক্ষেত্রে ব্যাংক হলো ট্রাস্টি বা আমানতদার (Trustee) এবং গ্রাহক হলো সুবিধাভোগী (Beneficiary)।

#### (খ) অনুধাবনমূলক উত্তর:
ব্যাংক হিসাব বন্ধ করার প্রধান কারণগুলো হলো: ১. গ্রাহকের মৃত্যু হলে বা দেউলিয়া ঘোষিত হলে, ২. আদালত কর্তৃক গার্নিশি অর্ডার জারি হলে, এবং ৩. গ্রাহক মস্তিষ্কবিকৃত বা অপ্রকৃতিস্থ হলে।

#### (গ) প্রয়োগমূলক উত্তর:
হিসাব স্থগিত ও বন্ধের আইনগত কারণ সারণি:

| সংঘটিত ঘটনা | আইনগত ধারা ও নিয়ম | ব্যাংকের তাৎক্ষণিক পদক্ষেপ |
| :--- | :--- | :--- |
| **আদালতের গার্নিশি অর্ডার জারি** | আদালতের লিখিত নিষেধাজ্ঞা যা হিসাবের অর্থ ছাড়ে বাধা দেয় | হিসাবে সব ধরনের অর্থ উত্তোলন ও ডেবিট লেনদেন ফ্রিজ করা |
| **দেউলিয়াত্ব ঘোষণা** | দেউলিয়া আইনের অধীনে ব্যক্তির আর্থিক দায়ভার আদালতের রিসিভারের হাতে চলে যায় | গ্রাহকের স্বাক্ষর ও চেক কার্যকর থাকার অধিকার বাতিল করা |
| **পারিবারিক দাবি** | গ্রাহক জীবিত থাকা অবস্থায় তৃতীয় পক্ষের কোনো আইনগত দাবি চলে না | পরিবারের যে কোনো চেক প্রত্যাখ্যান করতে ব্যাংক বাধ্য |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
ব্যাংকের পদক্ষেপের আইনি মূল্যায়ন সারণি:

| ব্যাংকের পদক্ষেপ | আইনগত যৌক্তিকতা | না মানলে ব্যাংকের ঝুঁকি |
| :--- | :--- | :--- |
| **চেক প্রত্যাখ্যান করা** | গার্নিশি অর্ডার জারি থাকার সময় টাকা দিলে আদালত অবমাননা হবে | আদালত কর্তৃক ব্যাংক জরিমানা ও শাস্তির মুখে পড়বে |
| **লেনদেন বন্ধ করা** | দেউলিয়া ব্যক্তির সমস্ত লেনদেনের ক্ষমতা রিসিভারের ওপর ন্যস্ত | প্রকৃত পাওনাদাররা ব্যাংকের বিরুদ্ধে মামলা করতে পারবে |
| **লকার সিলগালা করা** | আদালতের প্রতিনিধি ছাড়া লকার খোলার কোনো অনুমতি নেই | আত্মসাৎকৃত সম্পদ বেহাত হওয়ার দায় ব্যাংকে বর্তাবে |

**সিদ্ধান্ত:** ব্যাংক সম্পূর্ণ আইনসম্মত ও বাধ্যতামূলক দায়িত্ব পালন করেছে। আদালতের আদেশ ও দেউলিয়াত্বের নির্দেশনার মুখে চেক ফেরত দেওয়া ছাড়া ব্যাংকের কোনো বিকল্প ছিল না।
', 3);

