    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# ১৩শ অধ্যায়: কেন্দ্রীয় ব্যাংক (Central Bank)

---

### ১৩.১ কেন্দ্রীয় ব্যাংকের ধারণা
কেন্দ্রীয় ব্যাংক হলো কোনো দেশের সর্বোচ্চ আর্থিক প্রতিষ্ঠান যা সরকারের নিয়ন্ত্রণে পরিচালিত হয়ে মুদ্রা ও ঋণ ব্যবস্থা নিয়ন্ত্রণ করে, নোট প্রচলন করে এবং অন্যান্য ব্যাংকের অভিভাবক হিসেবে দেশের আর্থিক স্থিতিশীলতা রক্ষা করে।

---

### ১৩.২ প্রধান কার্যাবলি
১. **নোট ও মুদ্রা প্রচলন:** দেশে নতুন মুদ্রা ইস্যু করার একক ও অনন্য অধিকার কেন্দ্রীয় ব্যাংকের হাতে ন্যস্ত।
২. **সরকারের ব্যাংক:** সরকারের পক্ষে রাজস্ব জমা রাখা, বিভিন্ন ব্যয় নির্বাহ ও অভ্যন্তরীণ ও বৈদেশিক ঋণ পরিচালনা।
৩. **অন্যান্য ব্যাংকের ব্যাংক ও অভিভাবক:** বাণিজ্যিক ব্যাংকগুলোর রিজার্ভ সংরক্ষণ এবং নীতিগত দিকনির্দেশনা প্রদান।
৪. **ঋণদানের শেষ আশ্রয়স্থল (Lender of the Last Resort):** চরম তারল্য সংকটে বাণিজ্যিক ব্যাংককে সহায়তা প্রদান।
৫. **নিকাশ ঘর (Clearing House):** আন্তঃব্যাংক চেক ও দেনা-পাওনা নিষ্পত্তি করা।

---

### ১৩.৩ ঋণ নিয়ন্ত্রণের কৌশলসমূহ
- **সংখ্যাত্মক বা পরিমাণগত পদ্ধতি:**
  1. ব্যাংক হার নীতি (Bank Rate Policy)
  2. খোলা বাজার নীতি (Open Market Operation)
  3. জমার হার পরিবর্তন নীতি (Cash Reserve Ratio - CRR & SLR)
- **গুণগত বা নির্বাচিত পদ্ধতি:**
  1. ঋণের বরাদ্দকরণ ও সর্বোচ্চ সীমা নির্ধারণ
  2. মার্জিন বা জামানতের হার পরিবর্তন
  3. নৈতিক প্ররোচনা ও প্রত্যক্ষ ব্যবস্থা
', 1);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০১ (উচ্চ মূল্যস্ফীতি নিয়ন্ত্রণে ঋণ নিয়ন্ত্রণ পদ্ধতি)

### উদ্দীপক:
> দেশে আকস্মিক মুদ্রাস্ফীতি বেড়ে যাওয়ায় চাল, ডাল ও নিত্যপ্রয়োজনীয় দ্রব্যের মূল্য সাধারণ মানুষের নাগালের বাইরে চলে যায়। বাংলাদেশ ব্যাংক মুদ্রাবাজারে অর্থের অতিরিক্ত প্রবাহ রোধ করার জন্য বাণিজ্যিক ব্যাংকগুলোর ব্যাংক হার (Bank Rate) ও বিধিবদ্ধ জমার অনুপাত (CRR) বৃদ্ধি করে এবং বাণিজ্যিক ব্যাংকের অতিরিক্ত তহবিল খোলা বাজারে বন্ড বিক্রির মাধ্যমে তুলে নেয়। অন্যদিকে আন্তঃব্যাংক কোটি কোটি টাকার দেনা-পাওনা নিষ্পত্তির জন্য প্রতিদিন নির্ধারিত সময়ে নিকাশ ঘরের বৈঠক পরিচালনা করে।

---

### প্রশ্নাবলি:
- **(ক)** নিকাশ ঘর (Clearing House) কী? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** কেন্দ্রীয় ব্যাংককে ''ঋণদানের শেষ আশ্রয়স্থল'' বলা হয় কেন? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** উদ্দীপকে বাংলাদেশ ব্যাংক কর্তৃক প্রযুক্ত ঋণ নিয়ন্ত্রণ পদ্ধতির একটি কাঠামোগত ছক তৈরি করে ব্যাখ্যা কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** আন্তঃব্যাংক লেনদেন নিষ্পত্তি ও দেশের আর্থিক শৃঙ্খলা রক্ষায় কেন্দ্রীয় ব্যাংকের ভূমিকা সারণির মাধ্যমে মূল্যায়ন কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
যে সুনির্দিষ্ট স্থানে বা ব্যবস্থার অধীনে সদস্য বাণিজ্যিক ব্যাংকগুলো একত্রিত হয়ে পরস্পরের মধ্যকার আন্তঃব্যাংক চেক ও দেনা-পাওনা নিষ্পত্তি করে, তাকে নিকাশ ঘর বলে।

#### (খ) অনুধাবনমূলক উত্তর:
বাণিজ্যিক ব্যাংকগুলো যখন চরম আর্থিক সংকট বা তারল্য ঘাটতিতে পড়ে এবং অন্য কোথাও থেকে ঋণ সংগ্রহ করতে ব্যর্থ হয়, তখন কেন্দ্রীয় ব্যাংক সর্বশেষ ভরসা হিসেবে তাদের প্রয়োজনীয় ঋণ ও তহবিল সরবরাহ করে রক্ষা করে। তাই একে ঋণদানের শেষ আশ্রয়স্থল (Lender of the Last Resort) বলে।

#### (গ) প্রয়োগমূলক উত্তর:
বাংলাদেশ ব্যাংক কর্তৃক প্রযুক্ত সংখ্যাত্মক ঋণ নিয়ন্ত্রণ পদ্ধতি সারণি:

| ঋণ নিয়ন্ত্রণ পদ্ধতি | কেন্দ্রীয় ব্যাংকের গৃহীত পদক্ষেপ | বাণিজ্যিক ব্যাংকের ওপর প্রভাব | মুদ্রাবাজারের ওপর চূড়ান্ত প্রভাব |
| :--- | :--- | :--- | :--- |
| **১. ব্যাংক হার নীতি (Bank Rate)** | কেন্দ্রীয় ব্যাংক সুদের হার বৃদ্ধি করেছে | বাণিজ্যিক ব্যাংকগুলো ঋণের ওপর সুদের হার বাড়াতে বাধ্য হয় | ঋণের চাহিদা কমে বাজারে মুদ্রার সরবরাহ হ্রাস পায় |
| **২. জমার অনুপাত (CRR & SLR)** | কেন্দ্রীয় ব্যাংকে বাধ্যতামূলক নগদ জমার হার বাড়িয়েছে | বাণিজ্যিক ব্যাংকের ঋণদানযোগ্য তহবিল সংকুচিত হয় | ঋণ প্রবাহ হ্রাস পেয়ে মুদ্রাস্ফীতি নিয়ন্ত্রণে আসে |
| **৩. খোলা বাজার নীতি (Open Market)** | খোলা বাজারে ট্রেজারি বিল ও সরকারি বন্ড বিক্রি করেছে | বাণিজ্যিক ব্যাংকের অতিরিক্ত উদ্বৃত্ত তারল্য কেন্দ্রীয় ব্যাংকে চলে আসে | বাজার থেকে অতিরিক্ত নগদ অর্থ অপসারিত হয় |

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
কেন্দ্রীয় ব্যাংকের বহুমুখী ভূমিকা ও আর্থিক শৃঙ্খলা রক্ষা সারণি:

| কার্যাবলির ক্ষেত্র | বাংলাদেশ ব্যাংকের সুনির্দিষ্ট ভূমিকা | অর্থনীতিতে ইতিবাচক প্রভাব |
| :--- | :--- | :--- |
| **নিকাশ ঘর পরিচালনা** | প্রতিদিন শত শত বাণিজ্যিক ব্যাংকের কোটি কোটি টাকার চেক নগদে আদান-প্রদান না করে পারস্পরিক সমন্বয় করে | সময়, অর্থ ও নিরাপত্তার ঝুঁকি শূন্যে নামিয়ে আনে |
| **মুদ্রাস্ফীতি নিয়ন্ত্রণ** | সম্প্রসারণমূলক বা সংকোচনমূলক মুদ্রানীতি প্রয়োগ করে | নিত্যপ্রয়োজনীয় দ্রব্যের মূল্য স্থিতিশীল রাখে |
| **ঋণের শেষ আশ্রয়স্থল** | দেউলিয়াত্বের মুখে পড়া ব্যাংকে জরুরি নগদ সহায়তা দেয় | পুরো ব্যাংকিং ব্যবস্থার ওপর জনগণের আস্থা অটুট রাখে |
| **বৈদেশিক মুদ্রা রিজার্ভ** | ডলার ও স্বর্ণের রিজার্ভ সংরক্ষণ ও টাকার বিনিময় হার নিয়ন্ত্রণ | আন্তর্জাতিক আমদানি-রপ্তানি বাণিজ্যকে সুরক্ষিত রাখে |

**উপসংহার:** কেন্দ্রীয় ব্যাংক কেবল একটি ব্যাংক নয়, বরং দেশের সামগ্রিক আর্থিক স্থিতিশীলতা ও অর্থনৈতিক শৃঙ্খলার অভিভাবক ও মেরুদণ্ড।
', 2);

    INSERT INTO lessons (chapter_id, content_text, order_index)
    VALUES (v_chapter_id, '# 📝 সৃজনশীল প্রশ্ন - ০২ (আন্তঃব্যাংক নিকাশ ঘর ও বাংলাদেশ ব্যাংকের তদারকি ভূমিকা)

### উদ্দীপক:
> সোমবার সকালে ঢাকা শহরে সোনালী ব্যাংক জনতা ব্যাংকের ওপর কাটা ৫ কোটি টাকার চেক পায়; আবার জনতা ব্যাংক সোনালী ব্যাংকের ওপর কাটা ৪ কোটি টাকার চেক পায়। ব্যাংকের প্রতিনিধিরা নগদ টাকা টানাটানি না করে বাংলাদেশ ব্যাংকের নিকাশ ঘরে উপস্থিত হয়ে মাত্র ১ কোটি টাকার সমন্বয়ের মাধ্যমে শত কোটি টাকার দেনা নিষ্পত্তি করেন। একই দিনে বাংলাদেশ ব্যাংক আকস্মিক পরিদর্শনে গিয়ে দুটি বাণিজ্যিক ব্যাংকের ভুয়া ঋণ মঞ্জুরির প্রমাণ পেয়ে তাদের সতর্কবার্তা ও জরিমানা আরোপ করে।

---

### প্রশ্নাবলি:
- **(ক)** নোট ও মুদ্রা প্রচলনের একক অধিকার কার? *(জ্ঞানমূলক - ১ নম্বর)*
- **(খ)** কেন্দ্রীয় ব্যাংককে ''ব্যাংক ব্যবস্থার অভিভাবক'' বলা হয় কেন? *(অনুধাবনমূলক - ২ নম্বর)*
- **(গ)** উদ্দীপকে বর্ণিত নিকাশ ঘরের আন্তঃব্যাংক চেক নিষ্পত্তির প্রক্রিয়াটি ছকের সাহায্যে প্রদর্শন কর। *(প্রয়োগমূলক - ৩ নম্বর)*
- **(ঘ)** বাণিজ্যিক ব্যাংকগুলোর ওপর কেন্দ্রীয় ব্যাংকের কঠোর তদারকি ও পরিদর্শন ব্যবস্থা দেশের আর্থিক ব্যবস্থার সুরক্ষায় কতটা গুরুত্বপূর্ণ? সারণির মাধ্যমে বিশ্লেষণ কর। *(উচ্চতর দক্ষতা - ৪ নম্বর)*

---

### আদর্শ সমাধান:

#### (ক) জ্ঞানমূলক উত্তর:
দেশে কাগজের নোট প্রচলনের একমাত্র একক ও একচেটিয়া অধিকার কেন্দ্রীয় ব্যাংক বা বাংলাদেশ ব্যাংকের হাতে ন্যস্ত।

#### (খ) অনুধাবনমূলক উত্তর:
কেন্দ্রীয় ব্যাংক দেশের সকল তফসিলি বাণিজ্যিক ব্যাংক প্রতিষ্ঠার অনুমতি দেয়, তাদের বাধ্যতামূলক নগদ জমার রিজার্ভ সংরক্ষণ করে, নীতিগত দিকনির্দেশনা প্রদান করে এবং সংকটকালে ঋণ দিয়ে রক্ষা করে। তাই পিতা যেমন পরিবারকে পরিচালনা ও রক্ষা করেন, তেমনি কেন্দ্রীয় ব্যাংক সকল ব্যাংকের অভিভাবক হিসেবে কাজ করে।

#### (গ) প্রয়োগমূলক উত্তর:
নিকাশ ঘরের আন্তঃব্যাংক দেনা-পাওনা নিষ্পত্তি প্রক্রিয়া সারণি:

| ব্যাংকের নাম | অন্যের নিকট পাওনা চেক | নিজের ওপর দায়যুক্ত চেক | নিট দেনা / পাওনা নিষ্পত্তি |
| :--- | :---: | :---: | :--- |
| **সোনালী ব্যাংক** | ৫ কোটি টাকা (জনতার চেক) | ৪ কোটি টাকা | **১ কোটি টাকা পাবে** (উদ্বৃত্ত জমা) |
| **জনতা ব্যাংক** | ৪ কোটি টাকা (সোনালীর চেক) | ৫ কোটি টাকা | **১ কোটি টাকা প্রদান করবে** (হিসাব থেকে কর্তন) |
| **মোট সমন্বয়** | **৯ কোটি টাকার মোট চেক** | **নগদ আদান-প্রদান মাত্র ১ কোটি টাকা** | **৮ কোটি টাকার নগদ টানাহ্যাঁচড়া সাশ্রয়** |

**ব্যাখ্যা:** বাংলাদেশ ব্যাংকে উভয় ব্যাংকের চলতি হিসাব রয়েছে। বাংলাদেশ ব্যাংক শুধুমাত্র ১ কোটি টাকা জনতার হিসাব থেকে সোনালী ব্যাংকের হিসাবে ট্রান্সফার করে ৯ কোটি টাকার বিশাল লেনদেন নিষ্পত্তি করে দেয়।

#### (ঘ) উচ্চতর দক্ষতা উত্তর:
বাংলাদেশ ব্যাংকের তদারকি ও পরিদর্শনের অর্থনৈতিক গুরুত্ব সারণি:

| তদারকির ক্ষেত্র | বাংলাদেশ ব্যাংকের গৃহীত পদক্ষেপ | ব্যাংকিং ব্যবস্থার সুরক্ষা |
| :--- | :--- | :--- |
| **ভুয়া ঋণ প্রতিরোধ** | নিয়মিত সারপ্রাইজ অডিট ও ঋণ ফাইল যাচাই | আমানতকারীদের জমানো টাকার অপব্যবহার ও লুটপাট রোধ |
| **খেলাপি ঋণ নিয়ন্ত্রণ** | সিআইবি (CIB) রিপোর্টের মাধ্যমে খারাপ ঋণগ্রহীতাদের কালো তালিকাভুক্ত করা | বাণিজ্যিক ব্যাংকের মূলধন ঘাটতি রোধ ও স্থিতিশীলতা |
| **জরিমানা ও শাস্তিমূলক ব্যবস্থা** | অনিয়মে জড়িত কর্মকর্তা ও ব্যাংকের শাখা কার্যক্রম সীমিত করা | ব্যাংকিং খাতে সুশাসন ও জবাবদিহিতা নিশ্চিত হওয়া |

**চূড়ান্ত মন্তব্য:** বাণিজ্যিক ব্যাংকগুলোর ওপর কেন্দ্রীয় ব্যাংকের শক্তিশালী পর্যবেক্ষণ ও কঠোর নিয়ন্ত্রণই দেশের সাধারণ মানুষের আমানতের পূর্ণ নিরাপত্তা এবং আর্থিক শৃঙ্খলার মূল ভিত্তি।
', 3);

